window.STUDIA_CARDS=[{"id": "edukacja/fiszki:967ffdf1", "q": "Dlaczego autorka wybiera termin „psychologia edukacyjna”, a nie „wychowawcza” czy „wychowania”?", "a": "<p>Z dwóch powodów: potrzeby nawiązania do głównego nurtu refleksji i badań międzynarodowych (ang. <em>educational psychology</em>) oraz instytucjonalnego charakteru procesu edukacji. Ani „wychowawcza”, ani „wychowania” nie mają jednoznacznego odpowiednika w języku angielskim.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["nawiązanie do nurtu międzynarodowego (educational psychology)", "instytucjonalny charakter edukacji"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:8c0f5e98", "q": "Czym w rozdziale różni się wychowanie od edukacji (kształcenia)?", "a": "<p>Wychowanie odbywa się głównie (choć nie tylko) w kontekście <strong>domowym</strong> i dotyczy kształtowania zachowania. Edukacja (kształcenie) odbywa się głównie (choć nie tylko) w kontekście <strong>instytucjonalnym</strong> i dotyczy umiejętności szkolnych i akademickich. Dawniej „wychowanie” obejmowało jedno i drugie; z czasem pole znaczeniowe się rozszczepiło.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["wychowanie: dom, zachowanie", "edukacja: instytucja, umiejętności szkolne", "rozszczepienie pola znaczeniowego"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:d386a5fd", "q": "Czym psychologia kształcenia różni się od psychologii edukacyjnej?", "a": "<p>Psychologia kształcenia obejmuje część teoretyczno-koncepcyjną i badania podstawowe nad nabywaniem umiejętności szkolnych i akademickich, a aspekty praktyczne w znacznie mniejszym stopniu. Psychologię edukacyjną wyróżnia <strong>aplikacyjny kontekst</strong>: jest dyscypliną stosowaną.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["kształcenie: teoria i badania podstawowe", "edukacyjna: kontekst aplikacyjny (stosowana)"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:e57d99b8", "q": "Jakim celom służy psychologia edukacyjna jako dyscyplina stosowana?", "a": "<p>Podnoszeniu dobrostanu uczniów w ogóle, rozwiązywaniu problemów behawioralnych w placówkach edukacyjnych i optymalizowaniu efektów uczenia się u wszystkich kształcących się, szczególnie w grupach doświadczających trudności i barier. W wielu krajach wymaga odrębnego kształcenia podyplomowego.</p>", "src": "Dlaczego „psychologia edukacyjna”?", "k": ["dobrostan uczniów", "problemy behawioralne w placówkach", "optymalizacja efektów uczenia się"], "u": "wyklad-1.html", "s": "s1"}, {"id": "edukacja/fiszki:d1d3b36d", "q": "Czy psychologia szkolna to to samo co psychologia edukacyjna?", "a": "<p>Nie. Psychologia szkolna <strong>nie wyczerpuje</strong> zakresu psychologii edukacyjnej, ale nie ma powodu unikać tego terminu: jest częstym tytułem podręczników anglojęzycznych (Song i in., 2019; Lee, 2005). W Polsce bywa unikany, choć tłumaczenie podręcznika Greena wydano już 50 lat temu.</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["nie", "szkolna nie wyczerpuje zakresu edukacyjnej", "termin częsty w podręcznikach anglojęzycznych"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:456c49b5", "q": "Czym psycholog edukacyjny różni się od psychologa klinicznego dziecka, skoro mają tych samych klientów?", "a": "<p>Kontekstem instytucjonalnym i zadaniami. <strong>Edukacyjny:</strong> placówki edukacyjne (szkoła, poradnia psychologiczno-pedagogiczna), zmiany nieco bardziej zewnętrzne, w strategiach wychowawczych. <strong>Kliniczny:</strong> opieka zdrowotna, zdrowie psychiczne, sytuacja rodzinna; głębsze zmiany emocjonalne i w relacjach w rodzinie. Gdy potrzeby dziecka wykraczają poza kompetencje, psycholog edukacyjny po wstępnym rozpoznaniu <strong>przekierowuje</strong> klienta do klinicznego.</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["kontekst instytucjonalny i zadania", "edukacyjny: placówki, zmiany zewnętrzne", "kliniczny: zdrowie, głębsze zmiany", "przekierowanie do klinicznego"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:7235cee6", "q": "Jaką tezę o relacji do psychologii dziecięcej ryzykuje autorka?", "a": "<p>Że psychologia edukacyjna jest <strong>subdyscypliną psychologii dziecięcej</strong>, bo ma znacznie węższy zakres pracy. W diagnozie dodatkowo specjalizuje się w specjalnych potrzebach edukacyjnych i współpracuje z pedagogami przeprowadzającymi diagnozę.</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["subdyscyplina psychologii dziecięcej", "węższy zakres pracy", "specjalne potrzeby edukacyjne"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:bf88b999", "q": "Jak nazywa się psycholog w Wielkiej Brytanii i USA i jak ma się to do Polski?", "a": "<p><strong>Wielka Brytania:</strong> psycholog edukacyjny, specjalista spoza szkoły, opiekujący się rejonem i kilkoma szkołami, działający po „zgłoszeniu”. <strong>USA:</strong> psycholog szkolny, związany z lokalizacją w szkole, mniej reagujący na zgłoszenia, bardziej proaktywnie współpracujący z placówką. <strong>Polska:</strong> połączenie obu: psycholog rejonowy w poradni (jak w UK) i psycholog szkolny (jak w USA).</p>", "src": "Psychologia edukacyjna, szkolna i dziecka", "k": ["UK: psycholog edukacyjny spoza szkoły, rejon", "USA: psycholog szkolny w szkole, proaktywny", "Polska: połączenie obu"], "u": "wyklad-1.html", "s": "s2"}, {"id": "edukacja/fiszki:5e3420c4", "q": "Czym pedagogika różni się od psychologii edukacyjnej i gdzie się spotykają?", "a": "<p>Pedagogika to dyscyplina akademicka o odrębnej tradycji: kształtuje wizje edukacji, odpowiada, czym edukacja ma być, określa jej cele i analizuje wyzwania. Stawia podobne pytania o proces edukacji, ale inne metody i narzędzia. W praktyce psycholog współpracuje z pedagogiem szkolnym, terapeutą pedagogicznym, pedagogiem specjalnym i nauczycielem przedmiotowym. Obszar spotkania: <strong>polityka edukacyjna</strong>.</p>", "src": "Dyscypliny pokrewne", "k": ["pedagogika: wizje i cele edukacji", "inne metody i narzędzia", "współpraca z pedagogami i nauczycielami", "polityka edukacyjna"], "u": "wyklad-1.html", "s": "s3"}, {"id": "edukacja/fiszki:a07a98d6", "q": "Czym są studia edukacyjne i jaką analogię stawia autorka?", "a": "<p>Interdyscyplinarne podejście empiryczne, odrębne teoretycznie i metodologicznie od pedagogiki osadzonej w myśli filozoficznej. Analogia: <strong>psychologia edukacyjna ma się do psychologii kształcenia i wychowawczej tak, jak edukacja do studiów edukacyjnych i pedagogiki</strong>; obie są praktycznym zastosowaniem wiedzy z dziedzin podstawowych.</p>", "src": "Dyscypliny pokrewne", "k": ["interdyscyplinarne podejście empiryczne", "odrębne od pedagogiki filozoficznej", "analogia: edukacyjna – kształcenia jak edukacja – studia edukacyjne"], "u": "wyklad-1.html", "s": "s3"}, {"id": "edukacja/fiszki:8d323404", "q": "Dlaczego zdrowie publiczne jest dyscypliną pokrewną psychologii edukacyjnej?", "a": "<p>Zdrowie publiczne to zarazem nauka i działalność publiczna z wyraźnym systemem wartości; zapobiega chorobom i poprawia jakość życia w wymiarze społecznym i środowiskowym, a nie leczy pojedynczych osób. Psychologia edukacyjna podejmuje podobne wyzwania w węższym zakresie: tragiczny stan zdrowia psychicznego dzieci (Sajkowska, 2017; Krokstad, 2021) wymaga intensyfikacji opieki psychologicznej w populacji szkolnej i rozwiązań systemowych.</p>", "src": "Dyscypliny pokrewne", "k": ["nauka i działalność publiczna z systemem wartości", "zapobieganie, nie leczenie jednostek", "zły stan zdrowia psychicznego dzieci", "rozwiązania systemowe"], "u": "wyklad-1.html", "s": "s3"}, {"id": "edukacja/fiszki:94c55298", "q": "Dlaczego psychologia edukacyjna jest „hybrydą” i co znaczy cytat o „najokrutniejszym froncie”?", "a": "<p>Jako dyscyplina aplikacyjna łączy interdyscyplinarnie wiele podejść, teorii i ram konceptualnych, odpowiadając na pilne potrzeby społeczne. Szulevicz i Tanggaard (2017) nazywają ją „jednym z najokrutniejszych frontów współczesnej psychologii”. Ich podręcznik jest ceniony m.in. dlatego, że opisuje stan faktyczny praktyki zamiast narzucać oderwane od realiów teorie.</p>", "src": "Czym jest psychologia edukacyjna", "k": ["łączy wiele podejść i teorii", "odpowiada na pilne potrzeby społeczne", "„najokrutniejszy front” (Szulevicz, Tanggaard)", "opis realnej praktyki"], "u": "wyklad-1.html", "s": "s4"}, {"id": "edukacja/fiszki:de62b986", "q": "Jak Reynolds i Miller (2003) określają zakres psychologii edukacyjnej i jakie wyróżniają działy?", "a": "<p>Zakres: zastosowanie zasad psychologii do badania procesów uczenia się i rozwoju w kontekście systemu edukacji. Pięć działów: (1) poznawcze wyznaczniki uczenia się i rozwoju, (2) procesy socjokulturowe i relacyjne w nauczaniu, (3) realizacja podstawy programowej, (4) nietypowi uczniowie, (5) programy i polityka edukacyjna.</p>", "src": "Czym jest psychologia edukacyjna", "k": ["psychologia w procesach uczenia się i rozwoju w edukacji", "poznawcze wyznaczniki uczenia się", "procesy socjokulturowe i relacyjne", "podstawa programowa", "nietypowi uczniowie; programy i polityka"], "u": "wyklad-1.html", "s": "s4"}, {"id": "edukacja/fiszki:ecb314b7", "q": "Czym różnią się model teoretyczny, ramy konceptualne i ramy praktyczne?", "a": "<p><strong>Model / ramy teoretyczne:</strong> teorie ekspertów jako baza do interpretacji danych empirycznych. <strong>Ramy konceptualne:</strong> termin szerszy, czyli konceptualizacja całości projektu badawczego (temat, problem, pytania, literatura, metodologia, analiza, wnioski), bardziej indywidualna. <strong>Ramy praktyczne (wykonawcze):</strong> seria kroków i etapów stosowania modelu teoretycznego; dotyczą dyscypliny stosowanej i <strong>wypełniają lukę</strong> między modelami a ich skutecznym zastosowaniem.</p>", "src": "Modele teoretyczne i ramy praktyczne", "k": ["model teoretyczny: teorie ekspertów do interpretacji", "ramy konceptualne: konceptualizacja całego projektu", "ramy praktyczne: kroki stosowania modelu"], "u": "wyklad-1.html", "s": "s5"}, {"id": "edukacja/fiszki:c0640471", "q": "Jakie korzyści dają ramy praktyczne i jakie cechy postulują ich twórcy?", "a": "<p><strong>Korzyści:</strong> przejrzysta struktura złożonych problemów, jednoznaczne związki wyników diagnozy z planem interwencji, mniej niepotrzebnych działań diagnostycznych i arbitralnych zaleceń, lepsza jakość usług i satysfakcja praktyków. <strong>Cechy:</strong> transparentność i odpowiedzialność: rama jest znana i akceptowana przez wszystkich uczestników (psychologów, rodziców, ucznia, nauczycieli, placówkę), co służy szacunkowi, podmiotowemu traktowaniu i współpracy.</p>", "src": "Modele teoretyczne i ramy praktyczne", "k": ["przejrzysta struktura problemów", "związek diagnozy z interwencją", "mniej arbitralnych zaleceń", "transparentność i odpowiedzialność"], "u": "wyklad-1.html", "s": "s5"}, {"id": "edukacja/fiszki:7799f905", "q": "Na czym polega podejście pragmatyczne w psychologii edukacyjnej?", "a": "<p>Model, który w interpretacji problemu i szukaniu rozwiązań kieruje się <strong>przewidywaną w danym kontekście skutecznością</strong> zastosowania teorii lub ram. Problem można konceptualizować na wiele sposobów, a więcej niż jedno rozwiązanie może być skuteczne; wybór ma być elastyczny, nie arbitralny, i odwoływać się do zasobów w kontekście. W praktyce po wstępnej konsultacji psycholog decyduje o potrzebach klienta i ścieżce postępowania.</p>", "src": "Podejście pragmatyczne", "k": ["kieruje się przewidywaną skutecznością", "wiele konceptualizacji i rozwiązań", "wybór elastyczny, nie arbitralny", "zasoby w kontekście"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:537016f0", "q": "Co oznacza metafora bricoleura (majsterkowicza) i jaką cechę psychologa podkreślają badania SWPS?", "a": "<p>Majsterkowicz rozwiązuje różne problemy praktyczne dostępnymi środkami, niekoniecznie do tego przeznaczonymi ani doskonałymi, żeby rozwiązać problem skutecznie. Wymaga to kreatywności i otwartości na niestandardowe rozwiązania (Burnham, 2013; Szulevicz i Tanggaard, 2017). W badaniach SWPS (Czeranowska, 2022a) doświadczeni psychologowie wskazują <strong>kreatywność</strong> jako kluczowy przymiot.</p>", "src": "Podejście pragmatyczne", "k": ["rozwiązywanie problemów dostępnymi środkami", "kreatywność i otwartość", "kreatywność kluczowa (SWPS)"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:ae065c2a", "q": "Jakie obszary działania psychologa wymienia rozdział i dlaczego „zgłoszenie” to nie jedyny wariant pracy?", "a": "<p><strong>Diagnoza</strong> dziecka i środowiska (określenie barier, modyfikacja kontekstu), <strong>wsparcie</strong> (psychoedukacja, negocjacje, poradnictwo, elementy terapii, interwencja w kryzysie), <strong>przekierowanie lub współpraca</strong> z innymi specjalistami. Często „sprawą” jest sytuacja (np. przemoc rówieśnicza w klasie), a psycholog może i powinien <strong>proaktywnie</strong> tworzyć optymalne środowisko i prewencję.</p>", "src": "Podejście pragmatyczne", "k": ["diagnoza dziecka i środowiska", "wsparcie (psychoedukacja, poradnictwo, kryzys)", "przekierowanie, współpraca", "„sprawą” bywa sytuacja", "proaktywna prewencja"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:1b058ff0", "q": "Do jakiej refleksji zachęcają Katra i Sokołowska (2010) oraz Wicks (2013)?", "a": "<p><strong>Katra i Sokołowska:</strong> psychologowie szkolni mają się zastanowić, jakie modele i ramy pracy wybierają w realnych sytuacjach i czym się kierują: naturą wyzwania czy własnymi preferencjami. <strong>Wicks:</strong> z pozycji konstruktywizmu społecznego psychologowie mają osobiste opinie o tym, z jakich podejść korzystać, więc powinni zastanowić się, jak ich przekonania, doświadczenia, postawy i przygotowanie zawodowe wpływają na wybory; ramy w praktyce są bardzo zróżnicowane.</p>", "src": "Podejście pragmatyczne", "k": ["jakie modele wybierają i czym się kierują", "natura wyzwania czy własne preferencje", "wpływ przekonań i doświadczeń na wybory (Wicks)"], "u": "wyklad-1.html", "s": "s6"}, {"id": "edukacja/fiszki:1db6d70c", "q": "Jak definiują psychologię edukacji Skinner, Anderson, Stephens i Kolesnik?", "a": "<p><strong>Skinner</strong>: gałąź psychologii o nauczaniu i uczeniu się, obejmująca cechy i zachowania związane z edukacją. <strong>Anderson</strong>: zastosowanie „czystej” psychologii w edukacji, by uspołeczniać jednostkę i modyfikować jej zachowanie. <strong>Stephens</strong>: systematyczne badanie rozwoju edukacyjnego i rozwoju dziecka. <strong>Kolesnik</strong>: bada zjawiska i teorie, które pomagają wyjaśnić i usprawnić edukację. (Peel: nauka o edukacji.)</p>", "src": "Slajdy W1", "k": ["Skinner: nauczanie i uczenie się", "Anderson: zastosowanie psychologii", "Stephens: rozwój edukacyjny", "Kolesnik: wyjaśnić i usprawnić"], "u": "wyklad-1.html", "s": "p1"}, {"id": "edukacja/fiszki:4c2ea347", "q": "Czym różnią się nazwy: psychologia wychowania, rozwojowo-wychowawcza i psychologia edukacji?", "a": "<p><strong>Psychologia wychowania</strong> – badania podstawowe nad procesami kształcenia (Trempała). <strong>Rozwojowo-wychowawcza</strong> – podkreśla, że procesy wychowawcze i rozwojowe są nierozłączne. <strong>Psychologia edukacji</strong> – uwzględnia, że kształcenie trwa całe życie (edukacja ustawiczna), nie kończy się na szkole.</p>", "src": "Slajdy W1", "k": ["wychowania: badania podstawowe", "rozwojowo-wychowawcza: nierozłączność", "edukacji: kształcenie przez całe życie"], "u": "wyklad-1.html", "s": "p1"}, {"id": "edukacja/fiszki:8b9a3818", "q": "Jakie działy psychologii stosowanej składają się na psychologię edukacji i z jakich dziedzin akademickich ona czerpie?", "a": "<p>Stosowana: psychologia <strong>kształcenia i uczenia się, szkolna, pedagogiczna, wychowania</strong>. Akademicka: czerpie z psychologii <strong>poznawczej, społecznej, rozwoju i różnic indywidualnych</strong>.</p>", "src": "Slajdy W1", "k": ["kształcenia i uczenia się, szkolna", "pedagogiczna, wychowania", "poznawcza, społeczna", "rozwoju, różnic indywidualnych"], "u": "wyklad-1.html", "s": "p2"}, {"id": "edukacja/fiszki:79cbaea2", "q": "Kto był pionierem psychologii edukacji na świecie i w Polsce?", "a": "<p>Świat: <strong>William James, John Dewey, Edward L. Thorndike</strong>; badania etniczne – <strong>Mamie Phipps Clark i Kenneth Clark</strong>. Polska: <strong>Aniela Szycówna</strong> i <strong>Jan Władysław Dawid</strong>; „Przegląd Pedagogiczny” (1882), „Polskie Archiwum Psychologii” (1926), Zakład Psychologii Wychowawczej UW (1927/28), Katedra Psychologii Pedagogicznej UJ (1928), „Psychologia Wychowawcza” (1938).</p>", "src": "Slajdy W1", "k": ["James, Dewey, Thorndike", "Clarkowie – badania etniczne", "Szycówna, Dawid", "Przegląd Pedagogiczny 1882"], "u": "wyklad-1.html", "s": "p3"}, {"id": "edukacja/fiszki:3d61cc0f", "q": "Na czym opiera się behawioralne podejście do edukacji i wychowania?", "a": "<p>Stosowana analiza zachowania: dziecko zachowuje się tak, bo ten sposób okazał się w przeszłości <strong>korzystny</strong>. Zachowania niepożądane są <strong>wyuczone</strong>, więc można ich oduczyć. Przyczyny leżą w <strong>środowisku</strong>, które trzeba uwzględnić w modyfikacji. Zachowania kształtuje się przez <strong>wzmocnienia</strong>.</p>", "src": "Slajdy W1", "k": ["zachowanie było korzystne", "wyuczone → można oduczyć", "przyczyny w środowisku", "wzmocnienia"], "u": "wyklad-1.html", "s": "p4"}, {"id": "edukacja/fiszki:a96c1598", "q": "Jakie trzy elementy wiążą teorie społeczno-poznawcze i co zalicza się do czynników wewnętrznych?", "a": "<p><strong>Środowisko, zachowanie i czynniki wewnętrzne</strong> wpływają na siebie nawzajem. Czynniki wewnętrzne to przekonania, oczekiwania, motywacja, cele, wartości i emocje.</p>", "src": "Slajdy W1", "k": ["środowisko", "zachowanie", "czynniki wewnętrzne", "wzajemny wpływ"], "u": "wyklad-1.html", "s": "p4"}, {"id": "edukacja/fiszki:1900d830", "q": "Jakie dwie koncepcje konstruktywistyczne omówiono na wykładzie?", "a": "<p><strong>Poznawczo-rozwojowa</strong>: struktura poznawcza zmienia się dzięki procesom regulacyjnym, zaburzenie równowagi napędza rozwój, a edukacja go stymuluje. <strong>Przetwarzania informacji</strong>: psychika jako układ przetwarzający informacje o ograniczonej pojemności i wydajności; stąd m.in. technologie w nauczaniu.</p>", "src": "Slajdy W1", "k": ["poznawczo-rozwojowa: zaburzenie równowagi", "edukacja stymuluje rozwój", "przetwarzanie informacji", "pojemność i wydajność"], "u": "wyklad-1.html", "s": "p4"}, {"id": "edukacja/fiszki:18a5fe2d", "q": "Czym różnią się badania opisowe, korelacyjne, eksperymentalne i ewaluacyjne w psychologii edukacji?", "a": "<p><strong>Opisowe</strong> rejestrują zachowania i postawy, ale nie mówią o przyczynach. <strong>Korelacyjne</strong> pokazują związek i pozwalają przewidywać, ale nie przyczynowość (permisywność a niska samokontrola). <strong>Eksperymentalne</strong>: losowy przydział do grup, manipulacja zmienną niezależną (np. program zarządzania czasem), pomiar zależnej (oceny). <strong>Ewaluacyjne</strong>: skuteczność programów i ocenianie efektów uczenia się (sprawdzające, różnicujące).</p>", "src": "Slajdy W1", "k": ["opisowe: bez przyczyn", "korelacyjne: związek, nie przyczyna", "eksperyment: losowy przydział", "ewaluacyjne: skuteczność programów"], "u": "wyklad-1.html", "s": "p5"}, {"id": "edukacja/fiszki:329c0757", "q": "Jakie są rodzaje obserwacji i inne metody opisowe w psychologii edukacji?", "a": "<p>Obserwacja <strong>laboratoryjna, w naturalnym środowisku, uczestnicząca</strong> (np. Crowley i in., 2001: rodzice częściej wyjaśniali zjawiska naukowe chłopcom). Inne: wywiady i kwestionariusze, testy, badania psychofizjologiczne, studia przypadków, badania etnograficzne, grupy fokusowe, dzienniki.</p>", "src": "Slajdy W1", "k": ["laboratoryjna, naturalna, uczestnicząca", "wywiady, kwestionariusze, testy", "studia przypadków, etnografia", "fokusy, dzienniki"], "u": "wyklad-1.html", "s": "p5"}, {"id": "edukacja/fiszki:287af86d", "q": "Jaki jest zakres, cel i kluczowe obszary badań psychologii edukacji?", "a": "<p><strong>Zakres</strong>: strona ucznia (uczeń, proces, strategie i sytuacja uczenia się) i nauczyciela (nauczyciel, treść, sposób i sytuacja nauczania, ewaluacja). <strong>Cel</strong>: fakty i metody do rozwiązywania problemów dydaktycznych, postawa naukowa, wykorzystanie psychologii w wychowaniu i edukacji. <strong>Obszary</strong>: procesy poznawcze, emocjonalno-społeczne, różnice indywidualne, uwarunkowania rozwoju i wychowania.</p>", "src": "Slajdy W1", "k": ["strona ucznia i nauczyciela", "fakty i metody, postawa naukowa", "poznawcze, emocjonalno-społeczne", "różnice indywidualne, uwarunkowania"], "u": "wyklad-1.html", "s": "p6"}, {"id": "edukacja/fiszki:cc2aa11c", "q": "Czym jest praktyka oparta na dowodach i skąd się wywodzi?", "a": "<p>To podejmowanie decyzji o konkretnym kliencie na podstawie <strong>najlepszych dostępnych dowodów</strong> z badań, zintegrowanych z <strong>doświadczeniem praktyka</strong> i <strong>preferencjami klienta</strong>. Wywodzi się z <strong>medycyny opartej na dowodach</strong> (lata 80. XX w.): diagnoza → wybór metody na podstawie danych o skuteczności i skutkach ubocznych → monitorowanie i modyfikacja (Sackett i in.).</p>", "src": "Bednarek, rozdz. 5", "k": ["najlepsze dowody + doświadczenie + preferencje", "medycyna, lata 80.", "diagnoza, wybór, monitorowanie"], "u": "wyklad-1.html", "s": "e1"}, {"id": "edukacja/fiszki:9251ff74", "q": "Ile czasu mija między wykazaniem skuteczności metody a jej stosowaniem w praktyce?", "a": "<p>W medycynie średnio około <strong>17 lat</strong> (od 10 do 25; Balas i Boren): ok. 10 lat do podręczników i kolejne ok. 9 lat do upowszechnienia. Przy nowych technologiach nawet do 50 lat. W psychologii brak danych, ale nie ma powodu sądzić, że jest lepiej.</p>", "src": "Bednarek, rozdz. 5", "k": ["ok. 17 lat", "10–25 lat", "najpierw podręczniki, potem praktyka"], "u": "wyklad-1.html", "s": "e1"}, {"id": "edukacja/fiszki:cab2f808", "q": "Co bierze pod uwagę psycholog, wybierając strategię działania według APA?", "a": "<p>(1) <strong>Wiarygodność dowodów</strong>, (2) <strong>indywidualne cechy klienta</strong> (w tym preferencje i wartości), (3) <strong>własne doświadczenie zawodowe</strong>. Kodeks APA wymaga też informowania klienta, na ile metody są zweryfikowane empirycznie (standardy 2.04, 2.01e, 10.01b).</p>", "src": "Bednarek, rozdz. 5", "k": ["wiarygodność dowodów", "cechy klienta", "własne doświadczenie", "informowanie klienta"], "u": "wyklad-1.html", "s": "e2"}, {"id": "edukacja/fiszki:0f0c1cee", "q": "Wymień poziomy hierarchii wiarygodności dowodów od najsłabszego.", "a": "<p>Brak badań (konsensus ekspertów) → badania opisowe (obserwacja, studia przypadków) → wstępne testowanie skuteczności (np. eksperymenty jednoprzypadkowe) → zagregowane dane z sytuacji naturalnej (np. PISA) → badania procesu i wyniku → skuteczność w warunkach naturalnych (<em>effectiveness</em>) → testowanie skuteczności (<em>efficacy</em>: quasi-eksperyment, RCT) → synteza wielu badań (przegląd, systematyczny przegląd, <strong>metaanaliza</strong>).</p>", "src": "Bednarek, rozdz. 5", "k": ["brak badań, opisowe", "wstępne testowanie, dane naturalne", "process–outcome, effectiveness", "efficacy: RCT; metaanaliza"], "u": "wyklad-1.html", "s": "e2"}, {"id": "edukacja/fiszki:346c9566", "q": "Czym różni się efficacy od effectiveness?", "a": "<p><strong>Efficacy</strong> to skuteczność w optymalnych, kontrolowanych („laboratoryjnych”) warunkach, z wykazanym związkiem przyczynowym. <strong>Effectiveness</strong> to skuteczność w warunkach realnego życia (np. w poradni), z wieloma niekontrolowanymi zmiennymi – pokazuje wartość ekologiczną metody.</p>", "src": "Bednarek, rozdz. 5", "k": ["efficacy: warunki kontrolowane", "effectiveness: realne życie", "wartość ekologiczna"], "u": "wyklad-1.html", "s": "e2"}, {"id": "edukacja/fiszki:a9f19a32", "q": "Czym różni się quasi-eksperyment od RCT i czym jest metaanaliza?", "a": "<p><strong>RCT</strong>: losowy przydział do grup, manipulacja, grupa kontrolna, pomiar przed i po. <strong>Quasi-eksperyment</strong>: bez losowego przydziału (np. jedna metoda w klasie A, druga w klasie B), nieznacznie mniej wiarygodny. <strong>Metaanaliza</strong>: statystyczna synteza wyników wielu badań – jej wartość zależy od jakości badań źródłowych.</p>", "src": "Bednarek, rozdz. 5", "k": ["RCT: losowość, grupa kontrolna", "quasi: bez losowania", "metaanaliza: synteza statystyczna", "jakość badań źródłowych"], "u": "wyklad-1.html", "s": "e2"}, {"id": "edukacja/fiszki:da6790f2", "q": "Jakie zarzuty stawia się praktyce opartej na dowodach w edukacji i jak odpowiada na nie Bednarek?", "a": "<p><strong>Epistemologiczny</strong>: wąskie rozumienie dowodu, tylko RCT – fałsz, APA uznaje całą hierarchię. <strong>Standaryzacja</strong>: utożsamianie z testami zewnętrznymi – testy nie wynikają z EBP, a badania pokazują ich szkody. <strong>Autonomia</strong>: „książka kucharska” – autonomia praktyka jest podstawą EBP. <strong>Redukcjonizm</strong>: „ta sama pigułka” – EBP wymaga indywidualizacji i monitorowania. <strong>Prakseologiczny</strong>: model medyczny nie pasuje – EBP szuka skutecznej drogi od stanu wyjściowego do docelowego.</p>", "src": "Bednarek, rozdz. 5", "k": ["epistemologiczny", "standaryzacja i testy", "autonomia nauczyciela", "redukcjonizm, wykonalność"], "u": "wyklad-1.html", "s": "e3"}, {"id": "edukacja/fiszki:4358e397", "q": "Jakie skutki mają standardowe testy zewnętrzne według badań (Harlen i Deakin-Crick)?", "a": "<p>Zawężenie nauczania do prostych, łatwo mierzalnych umiejętności kosztem myślenia twórczego i krytycznego; przesunięcie celu edukacji na wynik testu; spadek <strong>motywacji wewnętrznej</strong>; negatywny obraz siebie i lęk u uczniów z niskimi wynikami. W nauce języków: <strong>efekt wymywania</strong> (<em>washback</em>) – koncentracja na tym, co sprawdza test.</p>", "src": "Bednarek, rozdz. 5", "k": ["zawężenie nauczania", "spadek motywacji wewnętrznej", "lęk, niski obraz siebie", "efekt wymywania"], "u": "wyklad-1.html", "s": "e3"}, {"id": "edukacja/fiszki:07d4ee99", "q": "Czego uczy przykład upuszczania krwi w teście na praktykę opartą na dowodach?", "a": "<p>Upuszczanie krwi wynikało z przyjętej teorii (humoralnej), było rekomendowane przez autorytety i powszechnie akceptowane, a niektórym pacjentom się poprawiało – ale teoria i skuteczność nie były zweryfikowane empirycznie. Wniosek: zgodność z teorią, autorytety i powszechność <strong>nie czynią praktyki opartej na dowodach</strong>.</p>", "src": "Bednarek, rozdz. 5", "k": ["teoria + autorytety + powszechność", "brak weryfikacji empirycznej", "to nie jest EBP"], "u": "wyklad-1.html", "s": "e4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:cccb0cdd", "q": "Czym jest samospełniające się proroctwo w edukacji i dlaczego jest groźne?", "a": "<p>To sytuacja, w której pierwotnie <strong>nietrafne</strong> oczekiwania (za niskie lub za wysokie) rodziców czy nauczycieli, przez ich mniej lub bardziej intencjonalne zachowania, z czasem <strong>stają się rzeczywistością</strong>. Szczególnie groźne u dzieci rzekomo zaburzonych – oczekiwane ograniczenia mogą przejść w realną niepełnosprawność. Nawet mały efekt (r ≈ 0,2) oznacza zmianę u ok. 10% dzieci.</p>", "src": "Trusz (2011)", "k": ["nietrafne oczekiwania", "zachowania dorosłych", "stają się rzeczywistością", "r ≈ 0,2 → ok. 10% dzieci"], "u": "wyklad-1-trusz.html", "s": "s1"}, {"id": "edukacja/wyklad-1-trusz-fiszki:01392418", "q": "Opisz eksperyment Pigmaliona i jego wyniki.", "a": "<p>Rosenthal i Jacobson (Oak School): wszystkich uczniów zbadano testem TOGA, nauczycielom powiedziano, że przewiduje on „rozkwit” intelektualny, i podano nazwiska <strong>losowo wybranych</strong> ok. 20% dzieci. Po 8 miesiącach dzieci z listy miały wyższy przyrost IQ (średnio +3,8 pkt), najsilniej w klasie I (+27,4 vs +12). Nauczyciele oceniali je też jako ciekawsze i szczęśliwsze; paradoksalnie dzieci z grupy kontrolnej, które zyskały na IQ, oceniano gorzej.</p>", "src": "Trusz (2011)", "k": ["losowy wybór „rozkwitających”", "manipulacja oczekiwaniami nauczycieli", "wyższy przyrost IQ, najsilniej w klasie I", "lepsza ocena zachowania; paradoks grupy kontrolnej"], "u": "wyklad-1-trusz.html", "s": "s2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:0ab79ccd", "q": "Jak oceniano wyniki replikacji eksperymentu Pigmaliona?", "a": "<p>Przeprowadzono ok. 500 replikacji. Spitz: na 19 eksperymentów do 1974 r. tylko 3 wykazały wpływ na IQ. Harris i Rosenthal: metaanalizy ponad 400 badań pokazują efekt o znaczeniu praktycznym – przeciętny w warunkach naturalnych, duży w eksperymentach. Brophy: oczekiwania wyjaśniają 3–10% wariancji osiągnięć, a wpływ może trwać latami.</p>", "src": "Trusz (2011)", "k": ["ok. 500 replikacji", "Spitz: mało udanych", "metaanalizy: realny efekt", "3–10% wariancji (Brophy)"], "u": "wyklad-1-trusz.html", "s": "s2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:8081f584", "q": "Czym jest efekt Golema? Omów badanie Rista.", "a": "<p><strong>Efekt Golema</strong> to negatywna odmiana samospełniającego się proroctwa. Rist obserwował klasę, w której nauczycielka po 8 dniach podzieliła dzieci przy stolikach rzekomo według zdolności, a faktycznie według <strong>statusu społeczno-ekonomicznego</strong>. Faworyzowała stolik 1; dzieci z niego kpiły z innych, a dzieci ze stolików 2 i 3 zaczęły nazywać siebie „głupkami”. IQ się nie różniło, ale ucierpiały motywacja i relacje.</p>", "src": "Trusz (2011)", "k": ["negatywna odmiana proroctwa", "podział według SES", "faworyzowanie i wrogość stolika 1", "przejęcie hierarchii przez klasę"], "u": "wyklad-1-trusz.html", "s": "s3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:bb2dc0d5", "q": "Jaką rolę w efekcie oczekiwań odgrywają autooczekiwania dziecka?", "a": "<p>Dziecko dąży do <strong>spójności</strong> zachowania ze schematem „ja”: przy niskiej ocenie siebie działa poniżej możliwości i unika kontaktów (chłopiec z IQ 115–125, przekonany o niskich zdolnościach, osiągnął potem 85–100). Weinstein: osiągnięcia lepiej przewidują oczekiwania nauczyciela razem z autooczekiwaniami i <strong>dostrzeganym faworyzowaniem</strong>. Negatywne oczekiwania mogą prowadzić do wyuczonej bezradności.</p>", "src": "Trusz (2011)", "k": ["spójność z obrazem „ja”", "działanie poniżej możliwości", "dostrzegane faworyzowanie", "wyuczona bezradność"], "u": "wyklad-1-trusz.html", "s": "s3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:9e93959f", "q": "Na czym polega efekt akumulacji oczekiwań? Podaj przykłady badań nad rodzicami.", "a": "<p>Gdy dziecko jest faworyzowane lub defaworyzowane w kilku środowiskach (szkoła i dom), łączna siła efektu rośnie (Jussim i Harber); etykiety mogą się sumować (piętna wielorakie). Englund i in.: oczekiwania matek zwiększały ich zaangażowanie w edukację, ale raczej wyniki dziecka wpływały na oczekiwania. Madon i in.: picie alkoholu przez dzieci najlepiej przewidywało przeszacowanie przez <strong>oboje</strong> rodziców – akumulacja dotyczyła tylko oczekiwań negatywnych.</p>", "src": "Trusz (2011)", "k": ["kumulacja wpływów z kilku środowisk", "piętna wielorakie", "Englund – zaangażowanie matek", "Madon – alkohol, tylko negatywne"], "u": "wyklad-1-trusz.html", "s": "s4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:c4ca36e6", "q": "Jakie cztery czynniki pośredniczą w komunikowaniu oczekiwań (Rosenthal)?", "a": "<p><strong>Klimat</strong> – więcej wsparcia emocjonalnego; <strong>sprzężenia zwrotne</strong> – więcej trafnych informacji zwrotnych i pochwał; <strong>wkład</strong> – więcej i trudniejszego materiału; <strong>wydajność</strong> – więcej okazji do pokazania wiedzy. Wszystkie wiążą się z osiągnięciami (Harris i Rosenthal), najsilniej klimat i wkład.</p>", "src": "Trusz (2011)", "k": ["klimat", "sprzężenia zwrotne", "wkład", "wydajność"], "u": "wyklad-1-trusz.html", "s": "s5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:72e8eed7", "q": "Jakie reguły pomagają ograniczyć negatywny efekt oczekiwań?", "a": "<p>Szukać informacji o <strong>zachowaniach</strong> dziecka w różnych sytuacjach; <strong>zawieszać ocenę</strong>; informacje wieloznaczne interpretować na korzyść dziecka; pokazywać, że zdolności zależą od <strong>wysiłku</strong>; porażki przypisywać chwilowemu brakowi zaangażowania, a sukcesy zdolnościom; angażować wszystkie dzieci; dawać konstruktywne informacje zwrotne.</p>", "src": "Trusz (2011)", "k": ["obserwacja zachowań", "zawieszanie oceny", "interpretacja na korzyść", "zdolności zależą od wysiłku", "angażowanie i konstruktywne informacje zwrotne"], "u": "wyklad-1-trusz.html", "s": "s5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:73fb25b0", "q": "Czym różni się efekt autooczekiwań od efektu oczekiwań interpersonalnych?", "a": "<p><strong>Autooczekiwania</strong> to oczekiwania wobec siebie, które utrudniają lub ułatwiają osiągnięcie celu (samoutrudnianie, placebo). <strong>Oczekiwania interpersonalne</strong> to oczekiwania jednej osoby wobec zachowania innej, które doprowadzają do pojawienia się tego zachowania – działają jak samospełniające się proroctwo.</p>", "src": "Slajdy W2", "k": ["autooczekiwania: wobec siebie", "samoutrudnianie, placebo", "interpersonalne: wobec innej osoby", "samospełniające się proroctwo"], "u": "wyklad-1-trusz.html", "s": "p1"}, {"id": "edukacja/wyklad-1-trusz-fiszki:a868514d", "q": "Jakie są trzy etapy samospełniającego się proroctwa i dwa poziomy potwierdzenia oczekiwań?", "a": "<p>Etapy: <strong>indukcja</strong> oczekiwań, <strong>mediacja (komunikacja)</strong> oczekiwań, <strong>behawioralne potwierdzenie</strong>. Potwierdzenie może być <strong>rzeczywiste</strong> (osoba naprawdę zmienia zachowanie) albo <strong>percepcyjne</strong> (obserwator widzi to, czego oczekiwał).</p>", "src": "Slajdy W2", "k": ["indukcja", "komunikacja", "potwierdzenie", "rzeczywiste vs percepcyjne"], "u": "wyklad-1-trusz.html", "s": "p1"}, {"id": "edukacja/wyklad-1-trusz-fiszki:122e2bc8", "q": "Czym różni się efekt Galatei od efektu Golema?", "a": "<p>Oba są odmianami efektu Pigmaliona. <strong>Galatea</strong>: wysokie oczekiwania nauczyciela bezpośrednio podnoszą kompetencje intelektualne i motywację ucznia. <strong>Golem</strong>: niskie oczekiwania obniżają kompetencje i motywację.</p>", "src": "Slajdy W2", "k": ["Galatea: wysokie oczekiwania → wzrost", "Golem: niskie oczekiwania → spadek", "kompetencje i motywacja"], "u": "wyklad-1-trusz.html", "s": "p2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:f854fd6b", "q": "Co pokazały badania Trouilloud i in. (2006) oraz Szumskiego i Karwowskiego (2019)?", "a": "<p><strong>Trouilloud</strong> (WF, 421 uczniów): wczesne oczekiwania nauczycieli wiązały się z późniejszą postrzeganą kompetencją, zwłaszcza pozytywne, i silniej przy niskim wspieraniu autonomii. <strong>Szumski i Karwowski</strong> (matematyka, 1488 uczniów 13–15 lat): efekt działa też u starszych uczniów, indywidualnie i grupowo; niski SES klasy i liczba uczniów z problemami wiążą się z negatywnymi oczekiwaniami.</p>", "src": "Slajdy W2", "k": ["efekt poza poznaniem (WF)", "silniej przy niskiej autonomii", "także u nastolatków", "poziom indywidualny i grupowy"], "u": "wyklad-1-trusz.html", "s": "p2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:93f45055", "q": "Na czym polega pryzmat starszego rodzeństwa (Seaver, 1973)?", "a": "<p>Oczekiwania nauczyciela wobec młodszego dziecka powstają na podstawie doświadczeń ze starszym rodzeństwem. Gdy uczy <strong>ten sam nauczyciel</strong>: dobre starsze rodzeństwo → efekt Galatei, słabe → efekt Golema. Przy <strong>innym nauczycielu</strong> efektu brak.</p>", "src": "Slajdy W2", "k": ["oczekiwania przez starsze rodzeństwo", "ten sam nauczyciel: Galatea lub Golem", "inny nauczyciel: brak efektu"], "u": "wyklad-1-trusz.html", "s": "p2"}, {"id": "edukacja/wyklad-1-trusz-fiszki:21621120", "q": "Jakie klasy zmiennych wyróżnia model Rosenthala?", "a": "<p><strong>A</strong> – dalsze (moderator) i <strong>B</strong> – bliższe (oczekiwania): zmienne niezależne. <strong>C</strong> – zachowania osoby mającej oczekiwania: proces pośredniczenia. <strong>D</strong> – bliższe (bezpośrednie) i <strong>E</strong> – dalsze (długoterminowe) wyniki: zmienne zależne.</p>", "src": "Slajdy W2", "k": ["A moderator, B oczekiwania", "C zachowanie nauczyciela", "D skutki bezpośrednie", "E skutki długoterminowe"], "u": "wyklad-1-trusz.html", "s": "p3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:8bed81bb", "q": "Skąd biorą się oczekiwania nauczycieli wobec uczniów?", "a": "<p>Z informacji uzyskanych <strong>przed pierwszym kontaktem</strong> (schematy poznawcze, stereotypy społeczne), z <strong>powierzchownych cech</strong> dziecka oraz z <strong>pierwszych obserwacji</strong> jego zachowań w szkole.</p>", "src": "Slajdy W2", "k": ["schematy i stereotypy przed kontaktem", "powierzchowne cechy", "pierwsze obserwacje"], "u": "wyklad-1-trusz.html", "s": "p3"}, {"id": "edukacja/wyklad-1-trusz-fiszki:af2f11b2", "q": "Czym są moderatory edukacyjnego proroctwa i jakie omówiono?", "a": "<p>To czynniki decydujące o <strong>kierunku i sile</strong> wpływu oczekiwań na zachowania i osiągnięcia; działają na etapie indukcji, komunikowania i potwierdzania. Omówiono: prywatne teorie inteligencji, schematy „ja” i poczucie wartości uczniów, atrybucje nauczycieli i uczniów, spostrzegane podobieństwo nauczyciela do ucznia, cechy nauczycieli.</p>", "src": "Slajdy W2", "k": ["kierunek i siła wpływu", "trzy etapy", "teorie inteligencji, schematy „ja”", "atrybucje, podobieństwo, cechy nauczyciela"], "u": "wyklad-1-trusz.html", "s": "p4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:10925fca", "q": "Jak prywatne teorie inteligencji nauczycieli wpływają na ich oczekiwania?", "a": "<p>Nauczyciel, który uważa inteligencję za <strong>cechę stabilną</strong>, ma <strong>sztywne</strong> oczekiwania. Ten, który uważa zdolności za <strong>zmienne</strong>, ma oczekiwania <strong>elastyczne</strong>. Prywatne teorie inteligencji uczniów też wpływają na ich zachowanie.</p>", "src": "Slajdy W2", "k": ["stabilna → sztywne oczekiwania", "zmienna → elastyczne", "teorie uczniów też działają"], "u": "wyklad-1-trusz.html", "s": "p4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:309a10a2", "q": "Którzy nauczyciele są najbardziej podatni na nietrafne oczekiwania?", "a": "<p>Ci o <strong>wysokim dogmatyzmie i autorytaryzmie</strong> oraz <strong>niskiej tolerancji niejednoznaczności</strong>. Podatność spada wraz z <strong>doświadczeniem</strong>, ale rośnie przy <strong>wypaleniu zawodowym</strong>.</p>", "src": "Slajdy W2", "k": ["dogmatyzm, autorytaryzm", "niska tolerancja niejednoznaczności", "doświadczenie zmniejsza", "wypalenie zwiększa"], "u": "wyklad-1-trusz.html", "s": "p4"}, {"id": "edukacja/wyklad-1-trusz-fiszki:5ded4577", "q": "Jak różnią się sprzężenia zwrotne wobec uczniów z wysokimi i niskimi oczekiwaniami?", "a": "<p>Uczniowie z <strong>wysokimi</strong> oczekiwaniami dostają więcej pozytywnych i <strong>adekwatnych</strong> informacji zwrotnych, ale są też częściej karani za zachowania niezgodne z oczekiwaniami. Uczniowie z <strong>niskimi</strong> dostają więcej negatywnych i <strong>nieadekwatnych</strong> (pozytywnych i negatywnych).</p>", "src": "Slajdy W2", "k": ["wysokie: więcej pozytywnych, adekwatnych", "wysokie: częściej karani za odstępstwa", "niskie: więcej negatywnych", "niskie: nieadekwatne"], "u": "wyklad-1-trusz.html", "s": "p5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:d8b2ffd9", "q": "Czym są czynniki „wydajność” i „wkład” w teorii czterech czynników?", "a": "<p><strong>Wydajność</strong>: stopień, w jakim nauczyciel daje uczniowi okazję do działania i wypowiedzi – dłużej czeka na dobrą odpowiedź i częściej wchodzi w interakcję z dziećmi o wysokich oczekiwaniach. <strong>Wkład</strong>: więcej i trudniejszego materiału oraz dodatkowy czas dla wybranych uczniów.</p>", "src": "Slajdy W2", "k": ["wydajność: okazje do wypowiedzi", "dłuższe, częstsze interakcje", "wkład: więcej trudniejszego materiału", "dodatkowy czas"], "u": "wyklad-1-trusz.html", "s": "p5"}, {"id": "edukacja/wyklad-1-trusz-fiszki:19bc9a37", "q": "Jakie wnioski dla praktyki płyną z badań nad efektem oczekiwań?", "a": "<p>Efekt słabo wpływa na samo IQ, ale nie wolno go ignorować. Nauczyciel powinien znać wpływ swoich oczekiwań, budować je na <strong>różnych źródłach</strong>, być <strong>otwarty</strong> na informacje sprzeczne i szukać <strong>pozytywnych</strong> oczekiwań wobec każdego ucznia.</p>", "src": "Slajdy W2", "k": ["nie ignorować mimo małego wpływu na IQ", "świadomość własnych oczekiwań", "różne źródła, otwartość", "pozytywne oczekiwania wobec każdego"], "u": "wyklad-1-trusz.html", "s": "p6"}, {"id": "edukacja/wyklad-2-fiszki:48e45f63", "q": "Porównaj podejścia do inteligencji: czynnik ogólny i wiele zdolności.", "a": "<p><strong>Czynnik ogólny</strong>: Spearman – g i zdolności specyficzne s; Cattell – inteligencja płynna (Gf, wrodzona, operacje na symbolach) i skrystalizowana (Gc, wiedza nabyta). <strong>Wiele zdolności</strong>: Guilford – 180 zdolności (treści × operacje × produkty), myślenie konwergencyjne vs dywergencyjne; Gardner – 7 niezależnych inteligencji; Sternberg – teoria triarchiczna.</p>", "src": "Ledzińska i Czerniawska", "k": ["Spearman g i s", "Cattell Gf i Gc", "Guilford 180, konwergencyjne/dywergencyjne", "Gardner – wielorakie"], "u": "roznice.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:5999455f", "q": "Wymień inteligencje wielorakie Gardnera i znaczenie tej teorii dla szkoły.", "a": "<p>Logiczno-matematyczna, językowa, muzyczna, przestrzenna, cielesno-kinestetyczna, interpersonalna, intrapersonalna. Gardner krytykuje dominację inteligencji akademickiej (werbalnej i logiczno-matematycznej) w szkole; uznaje, że każda inteligencja zależy od wrodzonych właściwości i środowiska, więc <strong>każdą można rozwijać</strong>.</p>", "src": "Ledzińska i Czerniawska", "k": ["7 inteligencji", "krytyka inteligencji akademickiej", "niezależność inteligencji", "każdą można rozwijać"], "u": "roznice.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:ea46138b", "q": "Jaki jest związek inteligencji z osiągnięciami szkolnymi?", "a": "<p>Korelacje IQ z ocenami są <strong>słabe, ale dodatnie i istotne</strong>, i maleją z poziomem kształcenia; IQ wyjaśnia ok. 25–30% wariancji wyników. Kierunek jest sporny (Sternberg – szybsza automatyzacja; Ackerman – rola na początku nabywania umiejętności). Mimo to żaden inny czynnik nie wyjaśnia więcej, a inteligencję można rozwijać w szkole.</p>", "src": "Ledzińska i Czerniawska", "k": ["słabe, istotne korelacje", "maleją z poziomem kształcenia", "25–30% wariancji", "sporny kierunek zależności"], "u": "roznice.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:ccb52ede", "q": "Na czym polega koncepcja inteligencji sprzyjającej powodzeniu życiowemu Sternberga?", "a": "<p>Inteligencja to zdolność osiągania sukcesu według <strong>osobistych standardów</strong> w danym kontekście. Składa się z trzech względnie niezależnych inteligencji: <strong>analitycznej</strong> (akademickiej, mierzonej IQ), <strong>twórczej</strong> (nowe problemy i idee) i <strong>praktycznej</strong> (zdrowy rozsądek, przystosowanie i kształtowanie otoczenia). Sukces wymaga ich harmonizacji, wykorzystania mocnych i kompensowania słabych stron.</p>", "src": "Ledzińska i Czerniawska", "k": ["sukces wg osobistych standardów", "analityczna", "twórcza", "praktyczna", "harmonizacja"], "u": "roznice.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:84e87e14", "q": "Scharakteryzuj wymiar refleksyjność–impulsywność i jego znaczenie dla uczenia się.", "a": "<p>Kagan: indywidualna tendencja w sytuacjach z kilkoma możliwymi rozwiązaniami. <strong>Impulsywni</strong> odpowiadają szybko, popełniają więcej błędów (losowych), lepiej zapamiętują mimowolnie i radzą sobie w zadaniach na czas i dywergencyjnych. <strong>Refleksyjni</strong> działają wolniej, popełniają mniej błędów, mają lepszą koncentrację, transfer i wyniki w zadaniach konwergencyjnych (początek nauki, przedmioty ścisłe). Wpływ jest silniejszy u młodszych; nauczyciele wyżej oceniają uczniów o podobnym stylu.</p>", "src": "Ledzińska i Czerniawska", "k": ["Kagan, niepewność rozwiązań", "impulsywni: szybko, błędy losowe", "refleksyjni: wolno, mniej błędów", "zadania konwergencyjne vs dywergencyjne", "zgodność stylu z nauczycielem"], "u": "roznice.html", "s": "s2"}, {"id": "edukacja/wyklad-2-fiszki:d2d5e0fb", "q": "Czym jest zależność–niezależność od pola i jak wiąże się z osiągnięciami?", "a": "<p>Witkin: stopień, w jakim spostrzeganie zależy od ogólnej organizacji pola. <strong>Niezależni</strong> (analityczni) wyodrębniają elementy i są odporni na kontekst; <strong>zależni</strong> (globalni) – trudno oddzielają części od całości, są wrażliwi na informacje społeczne. Niezależni lepiej organizują informacje, stosują więcej strategii i zwykle mają lepsze oceny, zwłaszcza z matematyki i przyrody; zależni wolą nauki humanistyczne i zawody społeczne.</p>", "src": "Ledzińska i Czerniawska", "k": ["Witkin", "niezależni – analityczni", "zależni – globalni, społeczni", "przewaga niezależnych w ocenach"], "u": "roznice.html", "s": "s2"}, {"id": "edukacja/wyklad-2-fiszki:37a2a0be", "q": "Opisz style myślenia Sternberga.", "a": "<p>„Zarządzanie umysłem” na wzór rządów: 13 stylów w 5 wymiarach (funkcje, formy, poziomy, zakres, skłonności). <strong>Typ I</strong> – kreatywne, złożone (legislacyjny, sądowniczy, hierarchiczny, globalny, liberalny); <strong>typ II</strong> – cenienie norm (wykonawczy, lokalny, monarchiczny, konserwatywny); <strong>typ III</strong> – zależnie od zadania (anarchiczny, oligarchiczny, wewnętrzny, zewnętrzny).</p>", "src": "Ledzińska i Czerniawska", "k": ["zarządzanie umysłem, 13 stylów", "typ I – kreatywne", "typ II – normatywne", "typ III – zależne od zadania"], "u": "roznice.html", "s": "s2"}, {"id": "edukacja/wyklad-2-fiszki:8d913de8", "q": "Jak cechy Wielkiej Piątki wiążą się z osiągnięciami edukacyjnymi?", "a": "<p><strong>Sumienność</strong> – najsilniejszy predyktor na każdym poziomie. <strong>Ugodowość</strong> – najsłabsza, niespójne wyniki. <strong>Neurotyczność</strong> – negatywna, coraz silniej na wyższych poziomach. <strong>Otwartość</strong> – pozytywna, rosnąca z poziomem kształcenia. <strong>Ekstrawersja</strong> – plus u młodszych, minus u młodzieży; zależy od metody (odkrywcza vs podająca). Wpływ jest głównie pośredni – przez motywację i strategie.</p>", "src": "Ledzińska i Czerniawska", "k": ["sumienność najsilniejsza", "neurotyczność negatywna, rośnie", "otwartość pozytywna", "ekstrawersja zależna od wieku i metody", "wpływ pośredni"], "u": "roznice.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:1bd1a485", "q": "Jakie style uczenia się wiążą się z cechami osobowości?", "a": "<p>Styl <strong>głęboki</strong> (zrozumienie) – z otwartością (i ekstrawersją); <strong>powierzchniowy</strong> (na pamięć) – z neurotycznością i ugodowością; <strong>strategiczny</strong> (maksymalizacja wyników) – z sumiennością i ekstrawersją, ujemnie z neurotycznością. Cechy wyjaśniają 22,7–43,6% wariancji stylów (Duff i in.).</p>", "src": "Ledzińska i Czerniawska", "k": ["głęboki – otwartość", "powierzchniowy – neurotyczność", "strategiczny – sumienność", "22,7–43,6% wariancji"], "u": "roznice.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:a280ea12", "q": "Jak ekstrawertycy i introwertycy różnią się w uczeniu się według Eysencka?", "a": "<p>Ekstrawertycy mają <strong>niższe pobudzenie korowe</strong> i szukają stymulacji; introwertycy – wyższe. W szkole podstawowej ekstrawertycy radzą sobie równie dobrze lub lepiej, w średniej i wyższej – introwertycy. Ekstrawertykom służy uczenie przez odkrywanie, introwertykom metoda podająca. Introwertycy mają lepszą pamięć długotrwałą, ekstrawertycy krótkotrwałą. Neurotycznym i introwertykom służą metody ustrukturalizowane.</p>", "src": "Ledzińska i Czerniawska", "k": ["pobudzenie korowe", "zależność od etapu kształcenia", "odkrywanie vs podająca", "pamięć długotrwała vs krótkotrwała"], "u": "roznice.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:b6dfae54", "q": "Jaki jest związek temperamentu z osiągnięciami szkolnymi?", "a": "<p>Wyniki są niespójne, ale: wytrwałość sprzyja, a aktywność i roztargnienie szkodzą (koncentracja na zadaniu); temperament wyjaśnia ok. 20% wariancji osiągnięć w szkole średniej. Lewowicki: siła pobudzenia i hamowania oraz ruchliwość procesów nerwowych sprzyjają osiągnięciom. Sprzyjają też wytrzymałość i żwawość, szkodzi reaktywność.</p>", "src": "Ledzińska i Czerniawska", "k": ["wytrwałość +, roztargnienie −", "ok. 20% wariancji", "siła i ruchliwość procesów nerwowych", "reaktywność szkodzi"], "u": "roznice.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:a10c6f42", "q": "Jakie są argumenty za indywidualizacją nauczania i jakie są jej formy?", "a": "<p>Argumenty: rozwój potencjału każdego ucznia; różnice w zdolnościach, stylach, osobowości, tempie, wiedzy wyjściowej, wsparciu domu i motywacji; bez indywidualizacji słabsi nie nadążają, a zdolni tracą motywację. Formy: <strong>grupy mieszane</strong> z różnicowaniem treści i tempa (diagnoza, monitorowanie) oraz <strong>grupy jednorodne</strong> (selekcja) – łatwiejsze dla nauczyciela, ale słabsi tracą wzorce. Dawanie najsłabszym tylko prostych zadań utrwala niskie osiągnięcia.</p>", "src": "Ledzińska i Czerniawska", "k": ["różnice między uczniami", "grupy mieszane – różnicowanie", "grupy jednorodne – selekcja", "ryzyko utrwalania niskich osiągnięć"], "u": "roznice.html", "s": "s4"}, {"id": "edukacja/wyklad-2-fiszki:c8e86096", "q": "Czym są strategie uczenia się i jak dzieli je Grupa z Michigan?", "a": "<p>Strategie to świadome sposoby organizowania sytuacji w celu zapamiętania i wykorzystania informacji (Czerniawska). Grupa z Michigan: strategie <strong>poznawcze</strong> (przetwarzanie materiału: powtarzanie, elaboracja, organizowanie), <strong>metapoznawcze</strong> (kierowanie stosowaniem strategii) i <strong>zarządzania zasobami</strong> (warunki zewnętrzne i wewnętrzne).</p>", "src": "Ledzińska i Czerniawska", "k": ["świadome sposoby zapamiętywania", "poznawcze", "metapoznawcze", "zarządzania zasobami"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:5b5a3bcb", "q": "Porównaj strategie powtarzania, elaboracji i organizowania.", "a": "<p><strong>Powtarzanie</strong> – recytowanie, przepisywanie, podkreślanie; niskie zaangażowanie, przydatne na wstępie i do utrwalenia. <strong>Elaboracja</strong> – mnemotechniki, wyobrażenia, opis własnymi słowami, streszczanie; dodaje elementy wspierające pamięć. <strong>Organizowanie</strong> – grupowanie, plany, mapy pojęciowe; wymaga największej aktywności i jest najskuteczniejsze w nauce szkolnej i akademickiej.</p>", "src": "Ledzińska i Czerniawska", "k": ["powtarzanie – płytkie", "elaboracja – opracowanie", "organizowanie – najgłębsze, najskuteczniejsze", "przykłady każdej"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:420af2e5", "q": "Wymień kryteria opisu strategii poznawczych.", "a": "<p>Faza pamięci (zapamiętywanie, przypominanie), poziom aktywności (<strong>głębokie vs powierzchniowe</strong> – najważniejszy), zakres (ogólne vs specyficzne), ukierunkowanie (wewnętrzne vs zewnętrzne), rodzaj działań (werbalne vs niewerbalne), złożoność (proste vs złożone programy, np. SQ3R), naturalność (naturalne vs sztuczne), racjonalność (racjonalne vs magiczne).</p>", "src": "Ledzińska i Czerniawska", "k": ["faza pamięci", "głębokie vs powierzchniowe", "wewnętrzne vs zewnętrzne", "werbalne vs obrazowe", "naturalne/sztuczne, racjonalne/magiczne"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:ca3330f5", "q": "Na czym polega program SQ3R?", "a": "<p>Złożony program uczenia się z tekstu: <strong>Survey</strong> – pobieżny przegląd, struktura; <strong>Question</strong> – stawianie pytań; <strong>Read</strong> – aktywne czytanie w poszukiwaniu odpowiedzi; <strong>Recite</strong> – powtarzanie najważniejszych informacji; <strong>Review</strong> – sprawdzenie, czy wszystko zrozumiane. Polski odpowiednik: 2PSPS (przejrzyj, pytaj, szukaj odpowiedzi, powtarzaj, sprawdź).</p>", "src": "Ledzińska i Czerniawska", "k": ["Survey – przegląd", "Question – pytania", "Read – aktywne czytanie", "Recite i Review – powtórz i sprawdź"], "u": "wyklad-2.html", "s": "s5"}, {"id": "edukacja/wyklad-2-fiszki:19835e67", "q": "Jak zmienia się aktywność strategiczna z wiekiem?", "a": "<p>Liczba strategii rośnie do ok. <strong>12–15 r.ż.</strong>, potem maleje; rośnie udział strategii głębokich, wewnętrznych, złożonych i specyficznych, a maleje powierzchniowych, zewnętrznych, prostych, ogólnych i magicznych; poprawia się dopasowanie strategii do zadań oraz monitorowanie i kontrola. Rozwój zmierza do <strong>samoregulacji</strong>.</p>", "src": "Ledzińska i Czerniawska", "k": ["szczyt 12–15 lat", "więcej głębokich i wewnętrznych", "lepsze dopasowanie do zadań", "samoregulacja"], "u": "wyklad-2.html", "s": "s6"}, {"id": "edukacja/wyklad-2-fiszki:f16e5a9a", "q": "Jak notowanie może pełnić funkcję różnych strategii i jak uczyć notowania?", "a": "<p>Notatki <strong>dosłowne</strong> – strategia powtarzania (najmniej skuteczna); <strong>własnymi słowami</strong> z elementami graficznymi – elaboracja; <strong>mapy pojęciowe, notatki macierzowe, drzewka</strong> – organizowanie (najcenniejsze). Uczyć: pokazać różne sposoby, zachęcić do wypróbowania i oceny, nie narzucać stylu; mapy wymagają wprawy.</p>", "src": "Ledzińska i Czerniawska", "k": ["dosłowne – powtarzanie", "własnymi słowami – elaboracja", "mapy i macierze – organizowanie", "nie narzucać stylu"], "u": "wyklad-2.html", "s": "s6"}, {"id": "edukacja/wyklad-2-fiszki:e895d2bf", "q": "Jakie zasady obowiązują przy ćwiczeniu strategii poznawczych z uczniami?", "a": "<p>Systematyczność z wydłużanymi przerwami; krótka rozgrzewka (5–10 min) dopasowana do materiału; podanie celu i przypomnienie wiedzy; od zadań prostych do złożonych; omówienie sesji (gdzie stosować, co trudne, co zmienić); relaks; zachęta do ćwiczenia poza sesjami (dzienniczek strategii); pozytywna informacja zwrotna, a negatywna od razu ze wskazówką poprawy.</p>", "src": "Ledzińska i Czerniawska", "k": ["systematyczność", "rozgrzewka i cel", "od prostych do złożonych", "omówienie i relaks", "informacja zwrotna"], "u": "wyklad-2.html", "s": "s6"}, {"id": "edukacja/wyklad-2-fiszki:38d823ab", "q": "Czym jest funkcja promocyjna psychologa szkolnego i czym różni się od profilaktyki i interwencji?", "a": "<p>W modelu Katry psycholog pełni funkcje monitoringu, psychoprofilaktyki, interwencji i <strong>promocji</strong>. Profilaktyka i interwencja działają „poniżej zera” – usuwają problemy i doprowadzają do normy. Promocja (Jurkowski; łac. <em>promovere</em>) wspiera rozwój <strong>powyżej zera</strong>: to, co dobre, ma stać się lepsze; obejmuje całą osobę i cały bieg życia, twórczość, transgresję (Kozielecki), także u uczniów zdolnych i „trudnych”.</p>", "src": "Budziszewska", "k": ["cztery funkcje (Katra)", "profilaktyka i interwencja – poniżej zera", "promocja – rozwój powyżej normy", "cała osoba, bieg życia, transgresja"], "u": "wyklad-2.html", "s": "s7"}, {"id": "edukacja/wyklad-2-fiszki:4c99c4e8", "q": "Jakie kryteria dojrzałej osobowości mogą wyznaczać cele promocyjne?", "a": "<p><strong>Allport</strong>: samowiedza i refleksja, zainteresowania poza „ja”, dystans i poczucie humoru, własny system wartości, głęboki kontakt z innymi, praktyczne umiejętności, zaangażowanie w dobro wspólne. <strong>Adler</strong>: poczucie wspólnoty. <strong>Maslow</strong>: adekwatna percepcja, szacunek, autentyczność, krytycyzm wobec kultury. Współcześnie: <strong>podmiotowość</strong> (wolność od i do), kreatywność, samoregulacja, aktywność prospektywna.</p>", "src": "Budziszewska", "k": ["Allport – dojrzała osobowość", "Adler – poczucie wspólnoty", "Maslow – samorealizacja", "podmiotowość, samoregulacja"], "u": "wyklad-2.html", "s": "s7"}, {"id": "edukacja/wyklad-2-fiszki:cfb67bdd", "q": "Jakimi sposobami psycholog szkolny może realizować funkcję promocyjną?", "a": "<p><strong>Kształtowanie środowiska i budzenie świadomości</strong> pozaintelektualnych aspektów rozwoju (rozmowy, rady pedagogiczne, perspektywa całego życia, spotkania z ciekawymi ludźmi); <strong>rozwijanie kompetencji emocjonalnych i interpersonalnych</strong> (nazywanie emocji, empatia, asertywność, decentracja wg Selmana); <strong>dopasowanie doświadczeń szkolnych do etapów rozwoju</strong> (Erikson: kompetencja, tożsamość, intymność); <strong>dbałość o własny rozwój</strong> i modelowanie postaw.</p>", "src": "Budziszewska", "k": ["środowisko i świadomość – rzecznik rozwoju", "kompetencje emocjonalne i interpersonalne", "etapy Eriksona", "dbałość o siebie"], "u": "wyklad-2.html", "s": "s7"}, {"id": "edukacja/wyklad-2-fiszki:2c6e6aa1", "q": "Czym różnią się empiryczne i teoretyczne definicje uczenia się?", "a": "<p><strong>Empiryczne</strong> wiążą uczenie się z obserwowalnymi wydarzeniami – np. Guthrie: zmiany w zachowaniu, które następują jako rezultat zachowania. <strong>Teoretyczne</strong> wskazują mechanizmy: fizjologiczne, poznawcze albo traktują uczenie się jako modyfikację zachowania.</p>", "src": "Slajdy W3", "k": ["empiryczne: obserwowalne zdarzenia", "Guthrie", "teoretyczne: mechanizmy", "fizjologiczne, poznawcze, modyfikacja zachowania"], "u": "wyklad-2.html", "s": "p1"}, {"id": "edukacja/wyklad-2-fiszki:12c60452", "q": "Jak definiują uczenie się Hilgard i Marquis, Włodarski oraz J.R. Anderson?", "a": "<p><strong>Hilgard i Marquis</strong>: stosunkowo trwała zmiana w zachowaniu w rezultacie wzmacnianego ćwiczenia. <strong>Włodarski</strong>: zmiany niezależne wyłącznie od receptorów i efektorów, na podłożu indywidualnego doświadczenia; jeśli nietrwałe – zawsze z nowymi elementami. <strong>Anderson</strong>: względnie trwała zmiana w potencjale zachowaniowym – nowa wiedza, umiejętności, postawy. (Woodworth: zdobywanie nowej wiedzy i sposobów reagowania.)</p>", "src": "Slajdy W3", "k": ["Hilgard i Marquis: wzmacniane ćwiczenie", "Włodarski: indywidualne doświadczenie", "Anderson: potencjał zachowaniowy", "wiedza, umiejętności, postawy"], "u": "wyklad-2.html", "s": "p1"}, {"id": "edukacja/wyklad-2-fiszki:472941eb", "q": "Jak rozwija się uczenie się u ludzi i jakie są trzy warunki skutecznego uczenia się?", "a": "<p>Rozwój: warunkowanie → naśladowanie → uczenie się „szkolne” → samodzielne uczenie się i samokształcenie. Warunki: <strong>chcieć, potrafić, wysilić się</strong>. Skuteczne uczenie się to dokładne zapamiętanie, trwałe przechowanie i szybkie przypomnienie w niezmienionej postaci.</p>", "src": "Slajdy W3", "k": ["warunkowanie → naśladowanie", "szkolne → samokształcenie", "chcieć, potrafić, wysilić się", "zapamiętanie, przechowanie, przypomnienie"], "u": "wyklad-2.html", "s": "p2"}, {"id": "edukacja/wyklad-2-fiszki:2d15ca9b", "q": "Jak bywa rozumiany „styl uczenia się” i jakie typy opisuje popularny model?", "a": "<p>Jako preferowany <strong>kanał zmysłowy</strong>, jako <strong>aktywność</strong> podczas uczenia się albo jako <strong>przekonanie</strong> o preferowanym zmyśle. Popularny model: <strong>wzrokowiec</strong> (obrazy, diagramy, czytanie), <strong>słuchowiec</strong> (wykłady, dyskusje, ustne instrukcje), <strong>kinestetyk</strong> (ruch, działanie, manipulowanie).</p>", "src": "Slajdy W3", "k": ["kanał zmysłowy", "aktywność", "przekonanie", "wzrokowy, słuchowy, kinestetyczny"], "u": "wyklad-2.html", "s": "p3"}, {"id": "edukacja/wyklad-2-fiszki:8f182558", "q": "Dlaczego style uczenia się uznano na wykładzie za mit?", "a": "<p>Rzekome podstawy (dominacja półkulowa, Jung, Sternberg) <strong>nie uzasadniają</strong> stylów. Diagnoza opiera się na samoopisie, a narzędzia są <strong>nierzetelne</strong>. Dane o tym, że dopasowanie nauczania do stylu poprawia wyniki, są <strong>niewiarygodne</strong>. Zmysły współpracują (kiki–buba, podwójne kodowanie), więc zamiast stylów warto uczyć <strong>strategii</strong>.</p>", "src": "Slajdy W3", "k": ["brak podstaw teoretycznych", "nierzetelne narzędzia", "brak dowodów na dopasowanie", "zamiast stylów: strategie"], "u": "wyklad-2.html", "s": "p3"}, {"id": "edukacja/wyklad-2-fiszki:26ec57a6", "q": "Na czym polegają podwójne kodowanie i poziomy przetwarzania?", "a": "<p><strong>Podwójne kodowanie</strong>: informacje wzrokowe się werbalizuje, a werbalne wizualizuje – słowo z obrazem zapamiętuje się lepiej. <strong>Poziomy przetwarzania</strong> (Craik i Lockhart, 1972): fizyczny (najpłytszy), fonetyczny, semantyczny (najgłębszy) – im głębsze przetwarzanie, tym trwalsza pamięć.</p>", "src": "Slajdy W3", "k": ["werbalizowanie obrazów, wizualizowanie słów", "Craik i Lockhart 1972", "fizyczny → fonetyczny → semantyczny", "głębiej = trwalej"], "u": "wyklad-2.html", "s": "p3"}, {"id": "edukacja/wyklad-2-fiszki:d5d39ef1", "q": "Jakie są strategie poznawcze i ich przykłady dla zadań prostych i złożonych?", "a": "<p><strong>Powtarzanie</strong>: recytowanie; przepisywanie, dosłowne notatki, podkreślanie. <strong>Elaboracja</strong>: mnemotechniki, wyobrażenia; opis własnymi słowami, streszczenia, parafrazowanie. <strong>Organizowanie</strong>: grupowanie; plany, mapy pojęciowe.</p>", "src": "Slajdy W3", "k": ["powtarzanie: recytowanie, podkreślanie", "elaboracja: mnemotechniki, parafraza", "organizowanie: grupowanie, mapy pojęciowe", "proste vs złożone zadania"], "u": "wyklad-2.html", "s": "p4"}, {"id": "edukacja/wyklad-2-fiszki:7ea801b2", "q": "Według jakich kryteriów opisuje się strategie poznawcze?", "a": "<p>Faza procesu pamięciowego; stopień aktywności (aktywne/bierne, głębokie/powierzchowne); zakres stosowalności (specyficzne/ogólne); ukierunkowanie (wewnętrzne/zewnętrzne); rodzaj działań (werbalne/niewerbalne); złożoność (proste/złożone); naturalność (naturalne/sztuczne); racjonalność (racjonalne/magiczne).</p>", "src": "Slajdy W3", "k": ["faza pamięci", "aktywność, zakres, ukierunkowanie", "rodzaj, złożoność", "naturalność, racjonalność"], "u": "wyklad-2.html", "s": "p4"}, {"id": "edukacja/wyklad-2-fiszki:5a098e28", "q": "Z czego składają się strategie metapoznawcze?", "a": "<p><strong>Planowanie</strong> (kolejność, czas, miejsce, cele, sposób sprawdzenia), <strong>zarządzanie uczeniem się</strong> (sprawdzone sposoby, warunki, okazje do przećwiczenia, koncentracja), <strong>monitorowanie</strong> (postępy i zrozumienie w trakcie nauki) i <strong>ewaluacja</strong>.</p>", "src": "Slajdy W3", "k": ["planowanie", "zarządzanie", "monitorowanie", "ewaluacja"], "u": "wyklad-2.html", "s": "p5"}, {"id": "edukacja/wyklad-2-fiszki:c8860bb7", "q": "Co mierzy kwestionariusz MSLQ?", "a": "<p>MSLQ (Pintrich i in., 1991; polska wersja skrócona dla uczniów od 12 lat: Dłużniewska i Kucharczyk) ma skale <strong>motywacyjne</strong> (motywacja wewnętrzna i zewnętrzna, wartość zadania, poczucie kontroli i skuteczności, lęk egzaminacyjny) i <strong>poznawcze</strong> (powtarzanie, elaboracja, organizowanie, myślenie krytyczne, metapoznanie, czas i miejsce, wysiłek, uczenie grupowe, szukanie pomocy).</p>", "src": "Slajdy W3", "k": ["Pintrich i in.", "skale motywacyjne", "skale poznawcze", "zarządzanie zasobami"], "u": "wyklad-2.html", "s": "p5"}, {"id": "edukacja/wyklad-2-fiszki:177a7e68", "q": "Czym jest nauczanie i jak szkoła uczy uczenia się?", "a": "<p>Nauczanie to <strong>organizowanie uczenia się</strong> i pomoc w kształtowaniu aktywnej postawy poznawczej. Szkoła uczy uczenia się <strong>pośrednio</strong> (sposób nauczania i sprawdzania, programy, zmęczenie, rozkład zajęć, atmosfera, testy zewnętrzne) i <strong>bezpośrednio</strong> (lekcje o uczeniu się, strategie w trakcie lekcji). Postawy nauczyciela → prowadzenie lekcji → sprawdzanie → sposoby uczenia się uczniów.</p>", "src": "Slajdy W3", "k": ["organizowanie uczenia się", "wpływ pośredni", "wpływ bezpośredni", "sposób sprawdzania kształtuje naukę"], "u": "wyklad-2.html", "s": "p6"}, {"id": "edukacja/wyklad-2-fiszki:5a5d408b", "q": "Co wykazali Lee i Boo (2022) o stylach nauczania?", "a": "<p>Nauczanie <strong>skoncentrowane na uczniu</strong> zwiększało <strong>zainteresowanie</strong> nauką języka obcego, a nauczanie <strong>skoncentrowane na nauczycielu</strong> poprawiało <strong>wyniki</strong> w nauce.</p>", "src": "Slajdy W3", "k": ["na uczniu → zainteresowanie", "na nauczycielu → wyniki"], "u": "wyklad-2.html", "s": "p6"}, {"id": "edukacja/wyklad-2-fiszki:ecf3cb03", "q": "Skąd uczniowie znają strategie uczenia się i jakich używają (Ledzińska, Czerniawska, Rzeńca)?", "a": "<p>Tylko 18% licealistów zna je ze szkoły (Ledzińska, 1988); w podstawówce ze szkoły ok. 20% uczniów sztywnych i 4% giętkich strategicznie (Czerniawska, 1999). Uczniowie klas III stosują tylko <strong>powierzchowne</strong> strategie (czytanie, powtarzanie, przepisywanie), bez metapoznawczych, a nauczyciele znają niewiele skutecznych strategii (Rzeńca, 2023). Oddziaływania szkoły są pośrednie i mogą być nieskuteczne.</p>", "src": "Slajdy W3", "k": ["18% ze szkoły (Ledzińska)", "sztywni vs giętcy (Czerniawska)", "tylko powierzchowne strategie (Rzeńca)", "nauczyciele znają niewiele"], "u": "wyklad-2.html", "s": "p6"}, {"id": "edukacja/wyklad-2-fiszki:91f7d113", "q": "Czym jest pamięć robocza i czym różni się jej pomiar od pomiaru pamięci krótkotrwałej?", "a": "<p>System do kontroli, regulacji i aktywnego utrzymywania informacji potrzebnych do bieżącego zadania, o ograniczonej pojemności dzielonej między przechowywanie i przetwarzanie. Test pamięci krótkotrwałej: zapamiętać i odtworzyć serię. Test pamięci roboczej (np. <strong>zakres operacyjny</strong>): zapamiętywać słowa, wykonując w międzyczasie działania arytmetyczne – kluczowe jest zadanie dodatkowe lub dystraktory.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["utrzymywanie + przetwarzanie", "ograniczona pojemność", "zakres operacyjny", "zadanie dodatkowe"], "u": "roznice.html", "s": "r1"}, {"id": "edukacja/wyklad-2-fiszki:f70c8053", "q": "Jak pamięć robocza wiąże się z osiągnięciami szkolnymi?", "a": "<p>Dobrze przewiduje wyniki z matematyki i języka (Gathercole); mierzona w wieku 5 lat przewiduje je lepiej niż <strong>inteligencja skrystalizowana</strong> (Alloway), a w polskim badaniu lepiej niż <strong>inteligencja płynna</strong>. U 6–7-latków β = 0,70. Do 11. roku życia najsilniej wiąże się z ocenami; u starszych ważniejsze są rozumowanie i kontrola uwagi (KAPP_A).</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["lepiej niż inteligencja skrystalizowana", "lepiej niż płynna", "β = 0,70 u 6–7-latków", "najsilniej do 11. r.ż."], "u": "roznice.html", "s": "r1"}, {"id": "edukacja/wyklad-2-fiszki:82eb9508", "q": "Jak pracować z uczniem o niskiej pamięci roboczej?", "a": "<p>Dawać <strong>krótkie polecenia</strong> z jedną–dwiema informacjami, ograniczać dystraktory, pomagać łączyć elementy wiedzy po przerwach i nowych wątkach, inaczej instruować przy zadaniach wieloetapowych. Potrzebna jest rzetelna diagnoza znormalizowanymi testami (np. KAPP_A) i ćwiczenia rozwijające pamięć roboczą.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["krótkie polecenia", "mniej dystraktorów", "wsparcie w zadaniach wieloetapowych", "diagnoza KAPP_A"], "u": "roznice.html", "s": "r1"}, {"id": "edukacja/wyklad-2-fiszki:772349b5", "q": "Czym jest bezradność intelektualna według modelu Kofty i Sędka?", "a": "<p>Stan wynikający z <strong>długotrwałego wysiłku poznawczego, który nie przynosi efektu</strong>. Prowadzi do <strong>wyczerpania poznawczego</strong>, które zaburza zwłaszcza złożone zadania i uniemożliwia uczenie się ze zrozumieniem. Po utrwaleniu nawet drobne bodźce związane z przedmiotem wyzwalają bezradność. Jest <strong>parcjalna</strong> – dotyczy konkretnego przedmiotu.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["wysiłek bez efektu", "wyczerpanie poznawcze", "brak uczenia się ze zrozumieniem", "parcjalna: jeden przedmiot"], "u": "roznice.html", "s": "r2"}, {"id": "edukacja/wyklad-2-fiszki:1dd00842", "q": "Skąd bierze się bezradność intelektualna w szkole i po czym ją rozpoznać?", "a": "<p>Z powtarzającego się <strong>braku zrozumienia</strong> nowego materiału mimo wysiłku – w dużej mierze przez styl prowadzenia lekcji, w którym nauczyciel nie promuje i nie monitoruje rozumienia. Sygnały: uczeń zgaduje, czeka na podpowiedzi, nie umie opisać problemu własnymi słowami, „pustka w głowie”, patrzenie na zegarek. Bezradność, a nie lęk, przewiduje osiągnięcia.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["brak zrozumienia mimo wysiłku", "styl prowadzenia lekcji", "zgadywanie, czekanie na podpowiedź", "silniejsza niż lęk"], "u": "roznice.html", "s": "r2"}, {"id": "edukacja/wyklad-2-fiszki:11e6a1f2", "q": "Jak bezradność intelektualna dotyczy starszych dorosłych?", "a": "<p>Starsi dorośli są bardziej bezradni intelektualnie wobec <strong>internetu, smartfona i bankowości internetowej</strong> niż młodzi; wobec komputera różnic nie ma. Bezradność (nie lęk) pośredniczyła w związku wieku z kompetencjami cyfrowymi – może wyjaśniać <strong>generacyjną przepaść cyfrową</strong>.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["internet, smartfon, bankowość", "komputer bez różnic", "przepaść cyfrowa", "bezradność, nie lęk"], "u": "roznice.html", "s": "r2"}, {"id": "edukacja/wyklad-2-fiszki:20704d7f", "q": "Czym jest zagrożenie stereotypem i co pokazał eksperyment Steele’a i Aronsona?", "a": "<p>Obawa przed byciem ocenianym przez pryzmat <strong>negatywnego stereotypu własnej grupy</strong> w sytuacji testowania ważnych zdolności. Steele i Aronson (1995): studenci afroamerykańscy, którzy zaznaczali rasę w metryczce lub słyszeli, że test mierzy zdolności, mieli niższe wyniki w werbalnej części GRE.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["obawa przed potwierdzeniem stereotypu", "sytuacja testowania", "metryczka z rasą", "niższe wyniki GRE"], "u": "roznice.html", "s": "r3"}, {"id": "edukacja/wyklad-2-fiszki:fba1b058", "q": "Od czego zależy podatność na zagrożenie stereotypem?", "a": "<p>Efekt pojawia się przy zadaniach <strong>trudnych</strong> (nie łatwych), u osób silnie <strong>identyfikujących się z własną grupą</strong> i silnie <strong>identyfikujących się z dziedziną</strong>, dla których jest ona ważna.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["trudne zadanie", "identyfikacja z grupą", "identyfikacja z dziedziną"], "u": "roznice.html", "s": "r3"}, {"id": "edukacja/wyklad-2-fiszki:403c9c13", "q": "Czym różni się model procesualny zagrożenia stereotypem od modelu czystego wysiłku i jak je pogodzić?", "a": "<p><strong>Procesualny</strong> (Schmader): niespójna triada postaw → negatywne emocje, monitorowanie, tłumienie stereotypu → wyczerpanie pamięci roboczej („nie zostaje naciśnięty hamulec”). <strong>Czystego wysiłku</strong> (Jamieson i Harkins): nadmierna motywacja, by zaprzeczyć stereotypowi → silne reakcje dominujące → błędy w zadaniach wymagających hamowania („za mocno wciśnięty gaz”). Integracja: najpierw <strong>mobilizacja</strong>, potem – bez efektu – <strong>demobilizacja</strong> (jak w bezradności).</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["procesualny: tłumienie, mało zasobów", "czysty wysiłek: nadmotywacja", "hamulec vs gaz", "mobilizacja → demobilizacja"], "u": "roznice.html", "s": "r3"}, {"id": "edukacja/wyklad-2-fiszki:5ed6b665", "q": "Co pokazały polskie badania zagrożenia stereotypem w szkole?", "a": "<p>Skala STAS: dziewczęta na matematyce i chłopcy na polskim. Zagrożenie stereotypem wiązało się z niższymi ocenami przez <strong>pamięć roboczą</strong> i <strong>bezradność intelektualną</strong>; efekt był silniejszy w starszych klasach (kumulacja). U chłopców bezradność wiązała się z niższą identyfikacją z przedmiotem. Stereotypy szkodzą obu płciom.</p>", "src": "Rydzewska, Bedyńska i Sędek, rozdz. 18", "k": ["dziewczęta – matematyka, chłopcy – polski", "mediatory: pamięć robocza, bezradność", "kumulacja w starszych klasach", "spadek identyfikacji z przedmiotem"], "u": "roznice.html", "s": "r3"}, {"id": "edukacja/wyklad-2-fiszki:888f02e4", "q": "Jaki jest związek inteligencji z ocenami szkolnymi i od czego zależą najwyższe osiągnięcia?", "a": "<p>Korelacja inteligencji z ocenami jest <strong>słaba</strong>. Najlepszych uczniów opisuje się wielowymiarowo: przez wskaźniki osiągnięć (punkty odcięcia, analiza profili ukrytych) i <strong>cechy motywacyjno-afektywne</strong> – wytrwałość, poczucie własnej skuteczności, zainteresowanie, motywację instrumentalną (Ziernwald i in., 2022).</p>", "src": "Slajdy W4", "k": ["słaba korelacja", "wskaźniki osiągnięć", "wytrwałość, skuteczność", "zainteresowanie, motywacja"], "u": "roznice.html", "s": "s1"}, {"id": "edukacja/wyklad-2-fiszki:4655b8fa", "q": "Które strategie uczenia się najsilniej przewidywały wyniki w nauce zdalnej (Neroni i in., 2019)?", "a": "<p><strong>Zarządzanie czasem, miejscem i wysiłkiem</strong> – najsilniejszy predyktor (częściej u kobiet); <strong>złożone strategie poznawcze</strong> – silny predyktor. Pojedyncze strategie i myślenie akademickie – brak związku. Kontakty z innymi w trakcie nauki – związek negatywny.</p>", "src": "Slajdy W4", "k": ["zarządzanie czasem i wysiłkiem", "złożone strategie", "pojedyncze: brak związku", "kontakty: negatywny"], "u": "roznice.html", "s": "v1"}, {"id": "edukacja/wyklad-2-fiszki:5ab35ae6", "q": "Czym jest refleksyjność – impulsywność według Kagana i jak wiąże się z wynikami?", "a": "<p>To styl poznawczy: tendencja w rozwiązywaniu problemów, gdy jest kilka możliwych rozwiązań i niepewność. <strong>Impulsywni</strong>: szybkie tempo (przewaga w testach na czas), więcej błędów, lepsze zapamiętywanie niezamierzone. <strong>Refleksyjni</strong>: lepsze odraczanie gratyfikacji, mniej błędów, lepsze zapamiętywanie zamierzone.</p>", "src": "Slajdy W4", "k": ["niepewność wyboru", "impulsywni: szybko, więcej błędów", "refleksyjni: dokładnie", "zapamiętywanie zamierzone vs niezamierzone"], "u": "roznice.html", "s": "s2"}, {"id": "edukacja/wyklad-2-fiszki:8d913de8", "q": "Jak cechy Wielkiej Piątki wiążą się z osiągnięciami edukacyjnymi?", "a": "<p><strong>Sumienność</strong>: pozytywnie, niezależnie od poziomu kształcenia, formy sprawdzania i kierunku studiów. <strong>Niska ugodowość</strong>: niższe wyniki. <strong>Neurotyczność</strong>: negatywnie na poziomie akademickim. <strong>Otwartość</strong>: pozytywnie, rośnie z wiekiem. <strong>Ekstrawersja</strong>: pozytywnie u dzieci, negatywnie później.</p>", "src": "Slajdy W4", "k": ["sumienność +", "neurotyczność − na studiach", "otwartość rośnie z wiekiem", "ekstrawersja: + dzieci, − później"], "u": "roznice.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:8323c563", "q": "Dlaczego sumienność sprzyja osiągnięciom akademickim (Waldeyer i in., 2022)?", "a": "<p>Działa przez <strong>zarządzanie czasem i regulację wysiłku</strong>: sumienność → strategie zarządzania czasem i wysiłkiem → osiągnięcia. To model <strong>moderowanej mediacji</strong>, w którym uwzględnia się też oceny ze szkoły średniej.</p>", "src": "Slajdy W4", "k": ["mediator: zarządzanie czasem i wysiłkiem", "moderowana mediacja", "oceny ze szkoły średniej"], "u": "roznice.html", "s": "s3"}, {"id": "edukacja/wyklad-2-fiszki:1ff43af5", "q": "Jakie style uczenia się wyróżnia Vermunt?", "a": "<p>Ukierunkowany na <strong>znaczenie</strong> (zrozumienie materiału), na <strong>reprodukcję</strong> (zapamiętanie), na <strong>zastosowania</strong> (praktyczne wykorzystanie) oraz <strong>nieukierunkowany</strong> (mieszanka bez wyraźnego kierunku).</p>", "src": "Slajdy W4", "k": ["znaczenie", "reprodukcja", "zastosowania", "nieukierunkowany"], "u": "roznice.html", "s": "v2"}, {"id": "edukacja/wyklad-2-fiszki:12348dbf", "q": "Jak neurotyzm i sumienność wiążą się ze stylami uczenia się Vermunta?", "a": "<p><strong>Neurotyzm</strong>: ujemnie ze stylem nastawionym na znaczenie i reprodukcję, dodatnio z <strong>brakiem ukierunkowania</strong>. <strong>Sumienność</strong>: dodatnio z trzema stylami ukierunkowanymi, ujemnie z brakiem ukierunkowania.</p>", "src": "Slajdy W4", "k": ["neurotyzm → brak ukierunkowania", "sumienność → style ukierunkowane"], "u": "roznice.html", "s": "v2"}, {"id": "edukacja/wyklad-2-fiszki:e15a0990", "q": "Jakie wnioski dla praktyki płyną z badań nad różnicami indywidualnymi?", "a": "<p>Efekty uczenia się zależą od wielu cech indywidualnych; o efektywności decyduje głównie <strong>własna aktywność</strong> uczącego się; brak złożonych strategii i <strong>sztywność strategiczna</strong> obniżają osiągnięcia.</p>", "src": "Slajdy W4", "k": ["wiele cech", "własna aktywność", "złożone strategie", "sztywność strategiczna"], "u": "roznice.html", "s": "s4"}, {"id": "edukacja/wyklad-3-fiszki:7f407fd1", "q": "Jakie role może pełnić psycholog szkolny według Sokołowskiej?", "a": "<p>„<strong>Człowiek środka</strong>” zanurzony w system szkolny; <strong>ekspert</strong> od wychowania i nauczania, wychodzący w opiniach poza system; <strong>badacz</strong> procesu, sytuacji i relacji wychowawczych; <strong>kreator</strong> nowych ujęć i strategii wychowawczych. Rola ma wymiar frontowy i gabinetowy, a pełna jej realizacja wymaga względnej niezależności od systemu szkoły.</p>", "src": "Sokołowska", "k": ["człowiek środka", "ekspert", "badacz", "kreator", "względna niezależność"], "u": "trudnosci.html", "s": "s1"}, {"id": "edukacja/wyklad-3-fiszki:0656d800", "q": "Co oznacza postulat Guryckiej, by psycholog był „człowiekiem środka”?", "a": "<p>Psycholog buduje kontakt z dzieckiem, rodzicem i nauczycielem, by rozwiązywać obecne i przyszłe <strong>konflikty wychowawcze</strong> i naprawiać ich wzajemne interakcje; ogólnie – wspiera oddziaływania wychowawcze. Przedmiotem jego zainteresowania jest <strong>interakcja wychowawcza</strong>. Nie wyręcza wychowawców, tylko pomaga im zrozumieć i mądrze kształtować sytuacje wychowawcze.</p>", "src": "Sokołowska", "k": ["kontakt z dzieckiem, rodzicem, nauczycielem", "konflikty wychowawcze", "interakcja wychowawcza", "nie wyręcza"], "u": "trudnosci.html", "s": "s2"}, {"id": "edukacja/wyklad-3-fiszki:902f215e", "q": "Czym jest interakcja wychowawcza?", "a": "<p>Relacja <strong>dwupodmiotowa</strong> – wpływają na nią i dorosły, i dziecko – oraz <strong>niesymetryczna</strong>: dorosły odpowiada za rozwój dziecka i ma prawo kontroli (większe kompetencje), a wychowanek wnosi własną inicjatywę w zdobywanie doświadczeń. Wychowanie jest „generatorem doświadczeń dziecka”, a każda lekcja ma też wymiar wychowawczy.</p>", "src": "Sokołowska", "k": ["dwupodmiotowa", "niesymetryczna", "odpowiedzialność dorosłego", "inicjatywa wychowanka"], "u": "trudnosci.html", "s": "s2"}, {"id": "edukacja/wyklad-3-fiszki:1311c850", "q": "Dlaczego psycholog szkolny nie powinien działać jak „pogotowie ratunkowe”?", "a": "<p>Model „pogotowia” (sama interwencja kryzysowa) ogranicza skuteczną pomoc i sprowadza się do wyręczania wychowawców („zarzucanie przypadkami”). Psycholog powinien być <strong>widoczny</strong> w szkole zanim pojawi się problem: monitoring, profilaktyka, promocja, dzielenie się wiedzą. Narzędziem jest np. <strong>monografia klasy</strong> (struktura nieformalna, cechy grupy, pozycje uczniów), przerywająca błędne koło kontaktu tylko w kryzysie.</p>", "src": "Sokołowska", "k": ["ogranicza pomoc, wyręczanie", "obecność przed kryzysem", "monitoring, profilaktyka, promocja", "monografia klasy"], "u": "trudnosci.html", "s": "s2"}, {"id": "edukacja/wyklad-3-fiszki:ff6e141c", "q": "Na czym polega rola psychologa jako eksperta od wychowania i nauczania?", "a": "<p>Gurycka: psycholog jest najpierw ekspertem od wychowania, potem od nauczania. Potrzebuje szerokiej, aktualizowanej wiedzy i <strong>refleksyjności</strong>. Szkoła nie „uczy i wychowuje”, tylko <strong>stwarza warunki</strong> do rozwoju – powinna uczyć uczenia się (Ledzińska), a nauczyciel potrzebuje przygotowania psychologicznego. Psycholog nie formułuje celów wychowania, tylko monitoruje proces z perspektywy wiedzy o rozwoju (Katra): „praca z”, nie „praca za”.</p>", "src": "Sokołowska", "k": ["najpierw wychowanie, potem nauczanie", "wiedza i refleksyjność", "szkoła stwarza warunki, uczy uczenia się", "nie formułuje celów; praca z, nie za"], "u": "trudnosci.html", "s": "s3"}, {"id": "edukacja/wyklad-3-fiszki:d6adae93", "q": "Jakie działania obejmuje praca psychologa w szkole według Guryckiej?", "a": "<p>Poradnictwo (diagnoza i pomocna informacja), opiekę i pomoc psychologiczną (towarzyszenie w problemie i przygotowanie na przyszłość), szeroką <strong>edukację psychologiczną</strong>, a także działania <strong>naukowe i popularyzatorskie</strong> – „przetwarzanie dorobku naukowego” na potrzeby szkoły. Zawód to <strong>służebność</strong>, a nie usługa na zlecenie.</p>", "src": "Sokołowska", "k": ["poradnictwo", "opieka i pomoc", "edukacja psychologiczna", "badania i popularyzacja", "służebność"], "u": "trudnosci.html", "s": "s4"}, {"id": "edukacja/wyklad-3-fiszki:31e6cf3d", "q": "Na czym polega frontowy i gabinetowy wymiar pracy psychologa?", "a": "<p>Metafora Jurkowskiego: niektóre zadania wymagają <strong>gabinetu</strong> (indywidualna diagnoza, rozmowa bez przerywania), inne – bycia „<strong>na froncie</strong>”, w codziennym życiu szkoły. Gabinet bywa sytuacją laboratoryjną – uczeń inaczej funkcjonuje w znanym otoczeniu. Wybór miejsca zależy od sytuacji, potrzeb ucznia i preferencji psychologa. Psycholog nie może biernie czekać na zgłoszenia.</p>", "src": "Sokołowska", "k": ["gabinet – diagnoza, spokojna rozmowa", "front – życie szkoły", "sztuczność gabinetu", "nie czekać biernie"], "u": "trudnosci.html", "s": "s5"}, {"id": "edukacja/wyklad-3-fiszki:6516d013", "q": "Czym są zewnątrzsystemowe ekspertyzy psychologiczne systemu oświaty?", "a": "<p>Jurkowski uważał je za ukoronowanie pracy psychologa szkolnego: ocena systemu dydaktycznego i wychowawczego w kategoriach <strong>psychologicznych</strong>, niezależnie od doktryn pedagogicznych, z pozycji eksperta nieuwikłanego we wspieranie jednej strony. Psycholog analizuje <strong>funkcje</strong> – zamierzone i niezamierzone konsekwencje (np. pogłębianie stratyfikacji społecznej), a nie formułuje celów. To efektywna forma transferu wiedzy.</p>", "src": "Sokołowska", "k": ["kategorie psychologiczne", "niezależność od doktryn", "funkcje, także niezamierzone", "transfer wiedzy"], "u": "trudnosci.html", "s": "s6"}, {"id": "edukacja/wyklad-3-fiszki:fb2606d3", "q": "Co oznacza, że psycholog powinien być reprezentantem swojej dziedziny?", "a": "<p>Choć jest formalnie w systemie oświaty, powinien zachować <strong>względną niezależność</strong> od oczekiwań instytucji (Jurkowski) i nie poprzestawać na tym, czego wymagają inni. Ma dzielić się wiedzą o rozwoju (prelekcje, wykłady, podręczniki), by inni dostrzegali ogólne tendencje rozwojowe poza własnym, wąskim doświadczeniem, oraz angażować się w działania naukowo-badawcze.</p>", "src": "Sokołowska", "k": ["względna niezależność", "nie tylko oczekiwania instytucji", "dzielenie się wiedzą", "szersza perspektywa rozwojowa"], "u": "trudnosci.html", "s": "s6"}, {"id": "edukacja/wyklad-3-fiszki:5a2b8acc", "q": "Jak WHO definiuje zdrowie psychiczne i jakie zarzuty stawia się tej definicji?", "a": "<p>WHO: <strong>brak zaburzeń</strong> i <strong>optymalny stan</strong> pozwalający realizować zdolności, radzić sobie z normalnym stresem, działać produktywnie i wnosić wkład w życie społeczności. Zarzuty: zbyt ogólna (podaje skutki, nie składniki) albo zbyt szczegółowa; inne propozycje: adaptacja i samoregulacja (poczucie koherencji), dynamiczny stan wewnętrznej równowagi (Galderisi).</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["brak zaburzeń + optymalny stan", "zdolności, stres, produktywność, wkład", "zbyt ogólna / szczegółowa", "Galderisi: dynamiczna równowaga"], "u": "trudnosci.html", "s": "z1"}, {"id": "edukacja/wyklad-3-fiszki:0aefee2c", "q": "Dlaczego ochrona zdrowia psychicznego dzieci i młodzieży jest tak ważna?", "a": "<p>Ok. 20% nastolatków ma problemy rozwojowe, emocjonalne lub w zachowaniu, ok. 12% – zaburzenia, a depresja rośnie z wiekiem (4% w wieku 12–17 lat, 9% w wieku 18 lat). <strong>Ponad 50% zaburzeń psychicznych zaczyna się przed 14. r.ż.</strong>, a zaniedbane problemy prowadzą do poważniejszych zaburzeń w dorosłości.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["20% problemów, 12% zaburzeń", "depresja rośnie z wiekiem", "ponad 50% przed 14. r.ż."], "u": "trudnosci.html", "s": "z1"}, {"id": "edukacja/wyklad-3-fiszki:461f5452", "q": "Na czym polega kompletny model zdrowia psychicznego?", "a": "<p>Psychopatologia i dobrostan to <strong>dwa odrębne wymiary</strong> (korelacja ok. −0,50, Keyes). Zdrowie optymalne: wysoki dobrostan i niska psychopatologia; słabe – odwrotnie; przeciętne – umiarkowane oba. Pozwala osobno zwiększać dobrostan i redukować objawy oraz monitorować oba wymiary.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["dwa wymiary", "r ≈ −0,50", "optymalne, przeciętne, słabe", "osobne oddziaływania"], "u": "trudnosci.html", "s": "z2"}, {"id": "edukacja/wyklad-3-fiszki:0077bb44", "q": "Czym różni się podejście transdiagnostyczne od sieciowego modelu zdrowia psychicznego?", "a": "<p><strong>Transdiagnostyczne</strong>: diagnozuje się i leczy nieprawidłowe <strong>procesy</strong>, a nie zaburzenia (urojenia, nie schizofrenię; anhedonię, nie depresję); wymiary transdiagnostyczne, np. samoocena, mają formy korzystne i niekorzystne. <strong>Sieciowe</strong>: zaburzenie to sieć wzajemnie napędzających się objawów (bezsenność → wyczerpanie → koncentracja → bezradność → smutek); wpływ na objaw centralny lub początkowy może rozbić sieć.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["transdiagnostyczne: procesy", "urojenia, anhedonia", "sieciowe: objawy się napędzają", "objaw centralny lub początkowy"], "u": "trudnosci.html", "s": "z2"}, {"id": "edukacja/wyklad-3-fiszki:443ab119", "q": "Czym jest kompetencja w zakresie zdrowia psychicznego (mental health literacy)?", "a": "<p>Wiedza o zdrowiu i zaburzeniach psychicznych oraz umiejętności jej zdobywania i używania: rozpoznawanie zaburzeń, szukanie wiarygodnych informacji, wychwytywanie czynników ryzyka, samopomoc, rozpoznanie momentu, gdy potrzebna jest pomoc profesjonalna, i skorzystanie z niej. Wiąże się z lepszym zdrowiem i jakością życia; wiedza o zaburzeniach zmniejsza stygmatyzację.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["wiedza o zaburzeniach", "wiarygodne źródła", "kiedy szukać pomocy", "mniej stygmatyzacji"], "u": "trudnosci.html", "s": "z2"}, {"id": "edukacja/wyklad-3-fiszki:9a908c46", "q": "Czym różni się ocena zdrowia psychicznego ucznia od diagnozy?", "a": "<p><strong>Ocena</strong> to wstępne rozeznanie zagrożenia na podstawie sygnałów nieprawidłowości i możliwości poradzenia sobie; dotyczy bieżącej sytuacji, opiera się na obserwacji i rozmowie; może ją zainicjować przygotowany nauczyciel lub rodzic. <strong>Diagnoza</strong> to pełny opis i wyjaśnienie stanu z rekomendacjami, prowadzona tylko przez specjalistę narzędziami diagnostycznymi. Ocena to nie „minidiagnoza”.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["ocena: wstępne rozeznanie", "może zacząć nauczyciel lub rodzic", "diagnoza: specjalista, pełny opis", "nie minidiagnoza"], "u": "trudnosci.html", "s": "z3"}, {"id": "edukacja/wyklad-3-fiszki:1d964431", "q": "Jakie są etapy oceny zdrowia psychicznego ucznia?", "a": "<p>Niepokój (zgłoszenie lub obserwacja) → pytanie: <strong>czy i jak zdrowie psychiczne dziecka jest/może być zagrożone?</strong> → analiza trudności i przejawów dobrostanu (model kompletny) → hipoteza o stanie zdrowia → informacja zwrotna, wsparcie, ewentualne rekomendacje → monitorowanie.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["kluczowe pytanie o zagrożenie", "trudności + dobrostan", "hipoteza", "informacja zwrotna, monitoring"], "u": "trudnosci.html", "s": "z3"}, {"id": "edukacja/wyklad-3-fiszki:72c8c724", "q": "Jak Kołakowski i Pisula dzielą niepokojące zachowania dzieci?", "a": "<p><strong>Drażniące</strong>: adekwatne do wieku, sporadyczne, niepokój wynika często z oczekiwań dorosłych. <strong>Niepożądane</strong>: nieadekwatne do wieku, spostrzegane jako problem – kluczowe dla oceny, bo zwiększają ryzyko utraty zdrowia i często są niezauważane (obniżony nastrój, wycofanie). <strong>Zaburzenia</strong>: zespoły symptomów z ICD-11 i DSM-5.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["drażniące: adekwatne do wieku", "niepożądane: zwiększają ryzyko", "zaburzenia: ICD, DSM"], "u": "trudnosci.html", "s": "z4"}, {"id": "edukacja/wyklad-3-fiszki:a4177229", "q": "Dlaczego w ocenie zdrowia psychicznego trzeba szukać zasobów i jakie mogą to być?", "a": "<p>Pełny obraz zdrowia (model kompletny) obejmuje deficyty i zasoby; przewaga deficytów to sygnał poważniejszego zagrożenia, a zasoby są punktem wyjścia wsparcia. Zasoby łatwo przeoczyć, bo negatywy silniej przyciągają uwagę. Osobiste: regulacja emocji, odporność, samoocena, optymizm, kompetencje społeczne. Środowiskowe: wspierająca rodzina, pozytywny klimat szkoły, akceptacja rówieśników, sieć wsparcia.</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["model kompletny", "negatywy przyciągają uwagę", "zasoby osobiste", "zasoby środowiskowe"], "u": "trudnosci.html", "s": "z4"}, {"id": "edukacja/wyklad-3-fiszki:9a49c5ef", "q": "Jakie szkolne czynniki chronią zdrowie psychiczne uczniów?", "a": "<p>Poczucie przynależności, pozytywny klimat szkoły, prospołeczna grupa rówieśnicza, wymaganie od uczniów odpowiedzialności i wzajemnej pomocy, okazje do sukcesu i rozpoznawania osiągnięć, zdecydowana niezgoda szkoły na przemoc (Szymańska).</p>", "src": "Trzebińska i Kuźmicz, rozdz. 7", "k": ["przynależność, klimat", "prospołeczni rówieśnicy", "odpowiedzialność, sukcesy", "niezgoda na przemoc"], "u": "trudnosci.html", "s": "z4"}, {"id": "edukacja/wyklad-3-fiszki:b15d5fdc", "q": "Czym są specjalne potrzeby edukacyjne i z czego mogą wynikać?", "a": "<p>To bariery w pełnym korzystaniu z edukacji o podłożu medycznym, psychologicznym lub środowiskowym (ok. 15–16,5% uczniów). Mogą wynikać z niepełnosprawności, zaburzeń zmysłów, autyzmu, ADHD, dysleksji, zaburzeń mowy, problemów emocjonalnych, <strong>szczególnych zdolności</strong>, a także z interakcji ucznia z kontekstem (drugi język, inna kultura, niski SES) lub problemów przejściowych (przemoc).</p>", "src": "Bednarek, rozdz. 8", "k": ["bariery w edukacji", "ok. 15–16,5% uczniów", "także zdolności", "interakcja z kontekstem"], "u": "trudnosci.html", "s": "n1"}, {"id": "edukacja/wyklad-3-fiszki:d6f04509", "q": "Jaki był kontekst powstania brytyjskiego raportu o SPE z 1978 r.?", "a": "<p>Raport był po części odpowiedzią na dyskryminację opisaną przez Bernarda Coarda: dzieci imigrantów z Karaibów przez wadliwą diagnozę uznawano za „edukacyjnie niezdolne” i kierowano do szkół specjalnych (5,4% vs 2,4% w szkołach masowych). Podobny problem może dziś dotyczyć uczniów romskich w Polsce.</p>", "src": "Bednarek, rozdz. 8", "k": ["Coard 1971", "wadliwa diagnoza dzieci imigrantów", "szkoły specjalne", "uczniowie romscy w Polsce"], "u": "trudnosci.html", "s": "n1"}, {"id": "edukacja/wyklad-3-fiszki:c66ed988", "q": "Jaka jest rola nauczyciela i psychologa we wspieraniu uczniów ze SPE?", "a": "<p><strong>Nauczyciel</strong> wykrywa ryzyko, wstępnie ocenia trudności, zachęca rodziców do konsultacji i dostosowuje nauczanie i ocenianie. <strong>Psycholog</strong> wspiera nauczycieli w rozumieniu SPE i wdrażaniu dostosowań, przekładając wiedzę naukową na praktyczne wskazówki. NIK: 28% rodziców skarży się na brak indywidualizacji.</p>", "src": "Bednarek, rozdz. 8", "k": ["nauczyciel: wykrywanie i dostosowania", "psycholog: tłumaczy naukę na praktykę", "NIK: 28% skarg"], "u": "trudnosci.html", "s": "n1"}, {"id": "edukacja/wyklad-3-fiszki:44e9954f", "q": "Jak Konwencja ONZ o prawach osób niepełnosprawnych definiuje niepełnosprawność i co to oznacza dla SPE?", "a": "<p>Niepełnosprawność wynika z <strong>interakcji</strong> osób z dysfunkcjami z barierami w postawach i środowisku (model społeczny). SPE to więc wynik interakcji cech ucznia ze środowiskiem edukacyjnym zaprojektowanym dla „przeciętnego” ucznia; diagnozuje się ucznia i jego środowisko, a dostosowania są <strong>prawem człowieka</strong>.</p>", "src": "Bednarek, rozdz. 8", "k": ["interakcja z barierami", "model społeczny", "diagnoza ucznia i środowiska", "prawo człowieka"], "u": "trudnosci.html", "s": "n2"}, {"id": "edukacja/wyklad-3-fiszki:1ffbecd4", "q": "Czym różni się projektowanie uniwersalne od racjonalnych usprawnień?", "a": "<p><strong>Projektowanie uniwersalne</strong>: tworzenie środowiska i usług użytecznych dla wszystkich bez adaptacji (przejście bez krawężnika; edukacja skoncentrowana na uczniu). <strong>Racjonalne usprawnienia</strong>: konieczne zmiany w konkretnym przypadku, bez nieproporcjonalnego obciążenia (rampa obok schodów, gdy winda jest zbyt droga; indywidualne dostosowania).</p>", "src": "Bednarek, rozdz. 8", "k": ["uniwersalne: dla wszystkich", "przejście bez krawężnika", "usprawnienia: konkretny przypadek", "rampa obok schodów"], "u": "trudnosci.html", "s": "n2"}, {"id": "edukacja/wyklad-3-fiszki:dfbf2dc7", "q": "Jak polskie prawo reguluje pomoc uczniom ze SPE?", "a": "<p>Rozporządzenie MEN z 9.08.2017 r. o pomocy psychologiczno-pedagogicznej: rozpoznawanie indywidualnych potrzeb i możliwości ucznia oraz czynników środowiskowych. Diagnoza w poradni → plan obejmujący <strong>zajęcia dodatkowe</strong> i <strong>zmianę metod nauczania i oceniania</strong>, z monitorowaniem efektów. Przepisy są zgodne z Konwencją ONZ.</p>", "src": "Bednarek, rozdz. 8", "k": ["rozporządzenie 2017", "diagnoza w poradni", "zajęcia dodatkowe + zmiana metod", "zgodne z Konwencją"], "u": "trudnosci.html", "s": "n2"}, {"id": "edukacja/wyklad-3-fiszki:83ae77a3", "q": "Dlaczego określenia typu „słaby uczeń” czy „dyslektyk” są szkodliwe?", "a": "<p>Utożsamiają problem z osobą (model wewnętrzny/medyczny): to osoba jest „słaba”, a nie jej wyniki w danym kontekście, więc nauczyciel nie szuka zmian w metodach. Badania (Granello): etykiety identyfikujące osobę z chorobą („chory psychicznie”, „schizofrenik”) wiążą się z mniejszą tolerancją i postawami autorytarnymi. Lepiej: „uczeń z dysleksją”.</p>", "src": "Bednarek, rozdz. 8", "k": ["problem = osoba", "zamyka zmianę metod", "postawy autorytarne", "uczeń z dysleksją"], "u": "trudnosci.html", "s": "n3"}, {"id": "edukacja/wyklad-3-fiszki:adfa7b26", "q": "Dlaczego nie należy nazywać dostosowań „ułatwieniami”?", "a": "<p>„Ułatwienie” sugeruje nieuczciwą przewagę, więc „sprawiedliwy nauczyciel” czuje moralny opór przed jego wprowadzeniem. Tymczasem dostosowania są prawnie wymagane i merytorycznie uzasadnione – pozwalają uczniowi ze SPE uczyć się i być ocenianym na równych prawach.</p>", "src": "Bednarek, rozdz. 8", "k": ["„ułatwienie” = przewaga", "opór sprawiedliwego nauczyciela", "dostosowanie = równe prawa"], "u": "trudnosci.html", "s": "n3"}, {"id": "edukacja/wyklad-3-fiszki:a4a75cab", "q": "Skąd biorą się psychopedagogiczne mity i neuromity w edukacji?", "a": "<p>Nauczyciele dostrzegają różnice między uczniami i szukają wyjaśnień, ale sięgają po uproszczone, publicystyczne źródła; mity powstają z błędnie uproszczonych badań lub badań na zwierzętach (OECD). Przykład: style uczenia się. Według Bednarek to sygnał, że psychologowie nie nadążają za potrzebami nauczycieli i powinni lepiej przekładać naukę na praktykę.</p>", "src": "Bednarek, rozdz. 8", "k": ["potrzeba wyjaśnienia różnic", "uproszczone źródła", "style uczenia się", "zadanie dla psychologów"], "u": "trudnosci.html", "s": "n3"}, {"id": "edukacja/wyklad-3-fiszki:52eeab26", "q": "Kto ponosi odpowiedzialność za diagnozę psychologiczną w poradni i czym jest „użytkownik testu” według APA?", "a": "<p>Wyłącznie <strong>psycholog</strong> – za plan, realizację i interpretację, nawet gdy opinię wystawia placówka i gdy część badań prowadzi pedagog. „Użytkownik testu” to osoba odpowiedzialna za wybór narzędzi, przeprowadzenie, obliczenie, analizę, interpretację i opinię; osoba, która tylko przeprowadza test i liczy wynik, nim nie jest.</p>", "src": "Bednarek, rozdz. 9", "k": ["tylko psycholog", "także gdy opinię wystawia placówka", "użytkownik testu = wybór + interpretacja"], "u": "trudnosci.html", "s": "d1"}, {"id": "edukacja/wyklad-3-fiszki:9dad02a0", "q": "Czym są Standardy diagnozy psychologicznej w edukacji (2018) i co jest w nich nowatorskie?", "a": "<p>Wskazówki PTP pod patronatem Rzecznika Praw Dziecka dla psychologów w poradniach i szkołach: od zasad etycznych przez hipotezy i ich weryfikację po przekazanie wyników odbiorcy. Nowatorski jest nacisk na <strong>konsekwencje diagnozy</strong> – planowanie interwencji i dostosowań oraz monitorowanie efektów. Według APA to raczej „wskazówki” niż „standardy”, bo nie ma sankcji.</p>", "src": "Bednarek, rozdz. 9", "k": ["PTP + RPD 2018", "nacisk na konsekwencje", "interwencje i monitorowanie", "„wskazówki”, nie standardy"], "u": "trudnosci.html", "s": "d1"}, {"id": "edukacja/wyklad-3-fiszki:e770eb6f", "q": "Jakie są trzy wersje rozdziału V ICD-10 i której nie wolno używać w diagnozie indywidualnej?", "a": "<p>(1) <strong>Granatowa</strong> – opisy kliniczne i wskazówki diagnostyczne dla praktyków; (2) <strong>zielona</strong> – badawcze kryteria diagnostyczne dla naukowców; (3) wersja dla lekarzy pierwszego kontaktu. Kryteriów <strong>badawczych</strong> nie wolno używać w praktyce: zawierają kryteria wykluczające, by wybrać „czyste przypadki”, a współwystępowanie zaburzeń jest powszechne.</p>", "src": "Bednarek, rozdz. 9", "k": ["granatowa: praktyka", "zielona: badania", "wersja POZ", "kryteria wykluczające krzywdzą"], "u": "trudnosci.html", "s": "d2"}, {"id": "edukacja/wyklad-3-fiszki:611a7314", "q": "Czym jest klasyfikacja ICF i jak ma się do ICD?", "a": "<p>Międzynarodowa klasyfikacja funkcjonowania, niepełnosprawności i zdrowia WHO (2001; ICF-CY dla dzieci, 2007), oparta na modelu biopsychospołecznym: niepełnosprawność to wynik związków stanu zdrowia z czynnikami osobowymi i środowiskowymi. Opisuje funkcjonowanie <strong>każdego</strong> człowieka. WHO zaleca używać jej <strong>komplementarnie</strong> z ICD: ICD opisuje zaburzenie, ICF jego wpływ na życie w danym kontekście.</p>", "src": "Bednarek, rozdz. 9", "k": ["WHO 2001 / CY 2007", "biopsychospołeczny", "dotyczy każdego", "komplementarna z ICD"], "u": "trudnosci.html", "s": "d2"}, {"id": "edukacja/wyklad-3-fiszki:9ae3f5bc", "q": "Na czym polega model rozbieżności IQ–osiągnięcia (AAD)?", "a": "<p>Zakłada, że inteligencja koreluje z umiejętnościami szkolnymi; trudność w uczeniu się stwierdza się, gdy wynik ucznia w wystandaryzowanym teście (np. czytania) jest istotnie <strong>niższy niż oczekiwany</strong> dla jego wieku i IQ. Kryterium stosują ICD i DSM. W Polsce brakuje norm uwzględniających przedział IQ, a model nie uwzględnia zasobów.</p>", "src": "Bednarek, rozdz. 9", "k": ["IQ koreluje z osiągnięciami", "wynik niższy od oczekiwanego", "ICD/DSM", "bez zasobów"], "u": "trudnosci.html", "s": "d3"}, {"id": "edukacja/wyklad-3-fiszki:78f0b89f", "q": "Jakie są zalety i wady modelu odpowiedzi na interwencję (RtI) jako modelu diagnozy?", "a": "<p>Trzy poziomy pomocy o rosnącej intensywności; kto nie reaguje, zostaje uznany za mającego specyficzne trudności. <strong>Zalety</strong>: tani, monitoruje wszystkich, przenosi akcent na metody nauczania. <strong>Wady</strong>: wiadomo tylko, że uczeń „nie reaguje” (<em>non-responder</em>), nic o przyczynach; te same strategie dla wszystkich; nie uwzględnia zasobów. Standardy zalecają gruntowną diagnozę niereagujących.</p>", "src": "Bednarek, rozdz. 9", "k": ["trzy poziomy", "tani, monitoruje wszystkich", "non-responders", "brak przyczyn i zasobów"], "u": "trudnosci.html", "s": "d3"}, {"id": "edukacja/wyklad-3-fiszki:fd526a82", "q": "Dlaczego sztywna diagnoza nozologiczna może być szkodliwa w edukacji?", "a": "<p>Nastawienie na „wyleczenie” frustruje, bo osoby o atypowym rozwoju realizują cele w swój sposób („miałem jeszcze na to papier”). Gdy dziecko nie spełnia kryteriów konkretnego zaburzenia, diagnoza bywa fiaskiem i nie daje pomocy – jakby pomoc należała się tylko osobom „posiadającym” zaburzenie. Wiele dostosowań zależy od symptomu, a nie od przyczyny.</p>", "src": "Bednarek, rozdz. 9", "k": ["frustracja „wyleczeniem”", "brak etykiety = brak pomocy", "dostosowania do symptomu"], "u": "trudnosci.html", "s": "d3"}, {"id": "edukacja/wyklad-3-fiszki:aa36a0ca", "q": "Czym jest diagnoza funkcjonalna i gdzie ją zakotwiczono w polskim prawie?", "a": "<p>Wielowymiarowe, wielokontekstowe rozpoznanie funkcjonowania osoby w środowisku (zasoby i deficyty) oraz możliwości rozwoju i <strong>modyfikacji środowiska</strong>; opiera się na modelu biopsychospołecznym i teorii Bronfenbrennera. W Polsce: § 2 rozporządzenia MEN z 9.08.2017 – rozpoznawanie potrzeb, możliwości i czynników środowiskowych, by umożliwić pełne uczestnictwo.</p>", "src": "Bednarek, rozdz. 9", "k": ["zasoby i deficyty w środowisku", "modyfikacja środowiska", "Bronfenbrenner", "rozporządzenie 2017 § 2"], "u": "trudnosci.html", "s": "d4"}, {"id": "edukacja/wyklad-3-fiszki:33fa713f", "q": "Czym model PSW i diagnoza neuropsychologiczna różnią się od AAD i RtI?", "a": "<p>Tworzą <strong>profil zasobów i ograniczeń</strong> w procesach poznawczych, służący szczegółowym zaleceniom dla nauczycieli; celem jest zrozumienie i jakość życia, a nie stwierdzenie syndromu. AAD i RtI służą głównie kwalifikacji do świadczeń i nie uwzględniają zasobów. Modele neuropsychologiczne (CHT, SNP/CHC, NDM) zakładają hierarchię procesów i brak „czystych” testów.</p>", "src": "Bednarek, rozdz. 9", "k": ["profil zasobów i ograniczeń", "zalecenia dla nauczycieli", "AAD/RtI = kwalifikacja", "hierarchia procesów"], "u": "trudnosci.html", "s": "d4"}, {"id": "edukacja/wyklad-3-fiszki:dbd6b49e", "q": "Dlaczego w diagnozie neuropsychologicznej nie można traktować wyniku jednego testu jako miary jednej funkcji?", "a": "<p>Nie ma testów „czystych”: wynik testu pamięci obciążają uwaga i percepcja w danej modalności. Procesy są zorganizowane hierarchicznie, więc o zaburzeniu na danym piętrze wnioskuje się po ocenie pięter niższych. Funkcje są też złożone (uwaga słuchowa ≠ wzrokowa, odporność na dystraktory ≠ przerzutność), więc nie wolno uogólniać wyniku na „uwagę w ogóle”.</p>", "src": "Bednarek, rozdz. 9", "k": ["brak czystych testów", "hierarchia pięter", "nie uogólniać"], "u": "trudnosci.html", "s": "d4"}, {"id": "edukacja/wyklad-3-fiszki:8d232a37", "q": "Jakie nawyki polskiej diagnozy dysleksji krytykuje Bednarek?", "a": "<p>(1) Przekonanie, że „nie można” diagnozować przed klasą III – niezgodne z klasyfikacjami i wiedzą o biologicznym podłożu; (2) „ryzyko dysleksji” jako quasi-diagnoza bez dostosowań i monitorowania; (3) zdublowana rediagnoza z rutynowym powtarzaniem IQ; (4) zdawkowe zalecenia mimo badania funkcji poznawczych; (5) wykluczanie dzieci z zaburzeniami współwystępującymi.</p>", "src": "Bednarek, rozdz. 9", "k": ["„nie przed klasą III”", "ryzyko bez dostosowań", "powtarzanie IQ", "zdawkowe zalecenia", "współwystępowanie"], "u": "trudnosci.html", "s": "d5"}, {"id": "edukacja/wyklad-3-fiszki:3e03b1c5", "q": "Kiedy powtórne badanie inteligencji w rediagnozie dysleksji jest uzasadnione?", "a": "<p>Inteligencja w wieku szkolnym jest względnie stała, a w modelu AAD bada się ją tylko, by wykluczyć niepełnosprawność intelektualną. Powtórka jest uzasadniona, gdy poprzedni wynik był <strong>graniczny</strong>, dziecko doznało <strong>urazu OUN</strong>, jego funkcjonowanie istotnie się <strong>pogorszyło</strong> albo poprzednie badanie było wadliwe (np. test werbalny u dziecka z zaburzeniami językowymi).</p>", "src": "Bednarek, rozdz. 9", "k": ["IQ względnie stałe", "wynik graniczny", "uraz OUN / pogorszenie", "błędne badanie"], "u": "trudnosci.html", "s": "d5"}, {"id": "edukacja/wyklad-3-fiszki:0760c2d2", "q": "W czym przejawia się funkcja symboliczna (reprezentacja) w okresie przedoperacyjnym?", "a": "<p>W naśladownictwie odroczonym, zabawie symbolicznej, rysunku, obrazie umysłowym i mowie.</p>", "src": "Slajdy W5", "k": ["naśladownictwo odroczone", "zabawa symboliczna", "rysunek", "obraz umysłowy", "mowa"], "u": "trudnosci.html", "s": "y1"}, {"id": "edukacja/wyklad-3-fiszki:538d78cc", "q": "Jak wspierać rozwój poznawczy i mowę przedszkolaka?", "a": "<p><strong>Rozwój poznawczy</strong>: rozmowy o przeszłych doświadczeniach, modelowanie zachowań, rysowanie zamiast kolorowania, czytanie książek zamiast odtwarzania bajek, zabawy symboliczne. <strong>Mowa</strong>: zachęcanie do mówienia, powtarzanie, korygowanie błędów, wzmacnianie, ćwiczenia językowe.</p>", "src": "Slajdy W5", "k": ["rysowanie, nie kolorowanie", "czytanie, nie bajki", "zachęcanie, powtarzanie", "korygowanie, wzmacnianie"], "u": "trudnosci.html", "s": "y1"}, {"id": "edukacja/wyklad-3-fiszki:fb1791c3", "q": "Jakie są etapy rozwoju rysunku dziecka?", "a": "<p><strong>Bazgroty</strong> (2–3 r.ż.: bezładna, kontrolowana, nazywana); okres <strong>schematyczny</strong> (głowonogi 3–4, głowotułowia 4–5, schemat uproszczony i wzbogacony); <strong>poschematyczny</strong> (realizm wrażeniowy 12–13, intelektualny 13–15, potem zahamowanie lub dalszy rozwój).</p>", "src": "Slajdy W5", "k": ["bazgroty", "głowonogi, głowotułowia", "schemat", "realizm wrażeniowy i intelektualny"], "u": "trudnosci.html", "s": "y2"}, {"id": "edukacja/wyklad-3-fiszki:3a05089b", "q": "Jakie są cechy rysunku we wczesnym dzieciństwie?", "a": "<p>Zmiana tematu w trakcie rysowania; rysowanie tego, co dziecko <strong>wie</strong>, a nie widzi; nierealistyczna kolorystyka; <strong>efekt rentgenowski</strong>; <strong>dysproporcja emocjonalna</strong>; specyficzne umiejscowienie na płaszczyźnie.</p>", "src": "Slajdy W5", "k": ["rysuje, co wie", "efekt rentgenowski", "dysproporcja emocjonalna", "umiejscowienie na płaszczyźnie"], "u": "trudnosci.html", "s": "y2"}, {"id": "edukacja/wyklad-3-fiszki:4f8cb991", "q": "Co wynika z badania Torgesena i in. (2001) nad intensywnymi programami czytania?", "a": "<p>Dwa programy o zupełnie innych proporcjach ćwiczeń – ADD (85% dekodowania pojedynczych słów) i EP (50% czytania w kontekście) – dały <strong>podobny</strong> wzrost wyników czytania. Dysleksji nie „leczy się” jedną metodą, ale intensywna, systematyczna praca przynosi postęp.</p>", "src": "Slajdy W5", "k": ["ADD: dekodowanie", "EP: kontekst", "podobne efekty", "liczy się intensywność"], "u": "trudnosci.html", "s": "y3"}, {"id": "edukacja/wyklad-3-fiszki:ef9bb23d", "q": "Jakie ćwiczenia poprawiają pisownię u osób z dysleksją, a jakie nie (Galuschka i in., 2020)?", "a": "<p>Największy wpływ mają zadania <strong>fonologiczne, ortograficzne i morfologiczne</strong>. Brak wpływu ma ćwiczenie strategii <strong>zapamiętywania zasad ortograficznych</strong>.</p>", "src": "Slajdy W5", "k": ["fonologiczne", "ortograficzne", "morfologiczne", "zasady na pamięć: brak efektu"], "u": "trudnosci.html", "s": "y3"}, {"id": "edukacja/wyklad-3-fiszki:a3b2154f", "q": "Jakie funkcje pełni diagnoza psychologiczna?", "a": "<p><strong>Deskryptywno-ewaluacyjną</strong> (jak jest?), <strong>eksplanacyjną</strong> (dlaczego tak jest?), <strong>predykcyjną</strong> (jak będzie?) i <strong>korekcyjną</strong> (co zrobić, aby osiągnąć stan pożądany?).</p>", "src": "Slajdy W5", "k": ["jak jest", "dlaczego", "jak będzie", "co zrobić"], "u": "trudnosci.html", "s": "y4"}, {"id": "edukacja/wyklad-3-fiszki:62631d30", "q": "Czym jest zasada Rumpelstilzchena i jak ilustruje ją przypadek Joasi?", "a": "<p>To „magiczna” wiara w moc słowa diagnozy – nazwanie problemu daje złudzenie wyjaśnienia. Joasia czytała dobrze, po diagnozie dysleksji w 5. klasie jej wyniki spadły, bo nauczyciele przypisali trudności dysleksji i <strong>przestali z nią pracować</strong> jak poprzedni. Etykieta zastąpiła działanie.</p>", "src": "Slajdy W5", "k": ["magiczna wiara w słowo", "etykieta zamiast działania", "spadek po diagnozie"], "u": "trudnosci.html", "s": "y4"}, {"id": "edukacja/wyklad-3-fiszki:443fdc73", "q": "Czym jest efekt Barnuma (Forera) i co oznacza dla diagnozy?", "a": "<p>To skłonność do uznawania ogólnikowych opisów osobowości za trafne wobec siebie, m.in. przez niedocenianie, jak powszechne są nieobserwowalne cechy (myśli, lęki, pragnienia). Wniosek: <strong>postrzegana trafność diagnozy nie jest dowodem jej trafności</strong>.</p>", "src": "Slajdy W5", "k": ["ogólnikowe opisy", "uznawane za trafne", "postrzegana ≠ rzeczywista trafność"], "u": "trudnosci.html", "s": "y4"}, {"id": "edukacja/wyklad-3-fiszki:8a1d7976", "q": "Na czym polega zależność ABC w analizie zachowania?", "a": "<p><strong>A</strong> – bodziec poprzedzający, <strong>B</strong> – zachowanie, <strong>C</strong> – konsekwencja. Przyczyną zachowania są jego <strong>konsekwencje</strong>: dziecko zachowuje się tak, bo w przeszłości to działało, więc zachowania można się też oduczyć.</p>", "src": "Slajdy W5", "k": ["antecedent", "behavior", "consequence", "konsekwencje podtrzymują"], "u": "trudnosci.html", "s": "y5"}, {"id": "edukacja/wyklad-3-fiszki:ee26372c", "q": "Jakie są etapy oceny funkcjonalnej zachowania trudnego?", "a": "<p>(1) Opis zachowania; (2) zbieranie informacji, kiedy się pojawia; (3) obserwacja warunków pojawiania się i niepojawiania; (4) stawianie hipotez o funkcji; (5) testowanie hipotez. Interwencja: rozwijanie zachowań pożądanych, redukcja trudnych, utrzymanie i generalizacja efektów.</p>", "src": "Slajdy W5", "k": ["opis", "kiedy się pojawia", "hipotezy o funkcji", "testowanie", "generalizacja"], "u": "trudnosci.html", "s": "y5"}, {"id": "edukacja/etyka-fiszki:fa6b3e30", "q": "Kto jest klientem w usługach psychologa edukacyjnego, a kto nie?", "a": "<p>Kontrakt, świadomą zgodę i tajemnicę można zawrzeć tylko z <strong>osobą</strong>. Klientami są dziecko (podmiot oddziaływania) i rodzice (zlecają i przyjmują wyniki), przy wsparciu rodzica – sam rodzic, przy konsultacji – nauczyciel. <strong>Nie są</strong> klientami: dyrektor, szkoła, kuratorium ani system; szkolenie i ekspertyza dla dyrektora to nie usługa psychologiczna.</p>", "src": "Bednarek, rozdz. 6", "k": ["tylko osoba", "dziecko + rodzice", "nauczyciel przy konsultacji", "nie dyrektor ani system"], "u": "etyka.html", "s": "k1"}, {"id": "edukacja/etyka-fiszki:8875d8f4", "q": "Jak psycholog ma formułować zalecenia dla szkoły, której możliwości są ograniczone?", "a": "<p>Uwzględnia zdolność placówki do ich wdrożenia, ale <strong>nie rezygnuje</strong> z rekomendacji optymalnych dla ucznia – jasno określa, w jakim stopniu różne formy dostosowań zaspokajają potrzeby. Tłumaczy nauczycielom zasadność zaleceń, korzyści i ryzyko ich niewdrożenia (ewentualnie w formie konsultacji).</p>", "src": "Bednarek, rozdz. 6", "k": ["uwzględnia możliwości szkoły", "nie rezygnuje z optimum", "stopień zaspokojenia potrzeb", "wyjaśnia ryzyko"], "u": "etyka.html", "s": "k1"}, {"id": "edukacja/etyka-fiszki:16331281", "q": "Czym różni się zgoda rodziców od przyzwolenia dziecka i co, gdy dziecko odmawia?", "a": "<p>Rodzice wyrażają <strong>pisemną, świadomą zgodę</strong> po zawarciu kontraktu. Dziecko, zwłaszcza młodsze, wyraża <strong>przyzwolenie</strong> po zrozumiałym wyjaśnieniu – podmiotowość przysługuje mu niezależnie od wieku. Przy sprzeciwie: bez presji, ocenić, czy wynika z lęku (wtedy pracować nad zaufaniem), a świadomą odmowę po zrozumieniu celu <strong>uwzględnić</strong>.</p>", "src": "Bednarek, rozdz. 6", "k": ["rodzice: pisemna zgoda", "dziecko: przyzwolenie", "zachęcać, nie zmuszać", "świadomą odmowę uwzględnić"], "u": "etyka.html", "s": "k2"}, {"id": "edukacja/etyka-fiszki:794432c6", "q": "Co zrobić, gdy jeden rodzic zgadza się na pomoc psychologiczną, a drugi nie?", "a": "<p>Władza rodzicielska przysługuje <strong>obojgu</strong> rodzicom, więc psycholog nie może wybrać, czyje zdanie respektuje. Jedynym rozwiązaniem jest skierowanie sprawy do <strong>sądu rodzinnego</strong>, który rozstrzyga istotne sprawy dziecka przy braku porozumienia rodziców.</p>", "src": "Bednarek, rozdz. 6", "k": ["władza obojga rodziców", "psycholog nie wybiera", "sąd rodzinny"], "u": "etyka.html", "s": "k2"}, {"id": "edukacja/etyka-fiszki:cfb6bb5c", "q": "Czy szkoła może uzyskać diagnozę ucznia wbrew rodzicom?", "a": "<p>Nie. Wywieranie presji autorytetem szkoły jest nieetyczne; psycholog buduje zaufanie, przedstawia korzyści i skutki zaniechania oraz informuje o dobrowolności. Tylko przy podejrzeniu zagrożenia zdrowia, życia lub poważnego zaniedbania można rozważyć wniosek do sądu rodzinnego o wgląd w sytuację rodziny, informując rodziców – nigdy jako perswazję i tylko gdy korzyści dla dziecka wyraźnie przeważają.</p>", "src": "Bednarek, rozdz. 6", "k": ["presja nieetyczna", "dobrowolność", "sąd tylko przy zagrożeniu", "korzyści dla dziecka, nie szkoły"], "u": "etyka.html", "s": "k2"}, {"id": "edukacja/etyka-fiszki:dc8e31ba", "q": "Kiedy psycholog może odstąpić od tajemnicy zawodowej z własnej inicjatywy?", "a": "<p>Gdy (1) <strong>poważnie zagrożone</strong> jest życie lub zdrowie klienta lub innych osób albo (2) <strong>stanowią tak ustawy</strong>. Interes, skuteczność czy prestiż placówki nie uzasadniają odstąpienia. Poza nagłymi sytuacjami psycholog konsultuje się, wyjaśnia klientowi, stara się uzyskać przyzwolenie i dokumentuje; w nagłym zagrożeniu działa od razu. Tajemnica nigdy nie wygasa.</p>", "src": "Bednarek, rozdz. 6", "k": ["zagrożenie życia/zdrowia", "przepis ustawy", "nie interes placówki", "nigdy nie wygasa"], "u": "etyka.html", "s": "k3"}, {"id": "edukacja/etyka-fiszki:43d68f39", "q": "Jakie informacje o dziecku psycholog przekazuje szkole i rodzicom?", "a": "<p><strong>Szkoła</strong>: to rodzice decydują o ujawnieniu opinii; bez ich pisemnej zgody nic ponad opinię, ze zgodą – minimum ważne dla dziecka. Współpraca ze szkołą nie uchyla tajemnicy. <strong>Rodzice</strong>: poznają wyniki i postępy, ale dziecko ma prawo do sekretów – przekazuje się wnioski, nie intymne zwierzenia. Zakres warto uzgodnić na początku.</p>", "src": "Bednarek, rozdz. 6", "k": ["rodzice decydują o ujawnieniu", "minimum dla szkoły", "wnioski, nie zwierzenia", "uzgodnić na starcie"], "u": "etyka.html", "s": "k3"}, {"id": "edukacja/etyka-fiszki:b4ae586f", "q": "Czym różni się społeczny od prawnego obowiązku denuncjacji?", "a": "<p><strong>Społeczny</strong> (art. 304 kpk): dotyczy przestępstw ściganych z urzędu, bez kary za niezgłoszenie – psycholog kieruje się dobrem dziecka i zwykle nie łamie tajemnicy. <strong>Prawny</strong> (art. 240 kk): zagrożony karą, dotyczy zamkniętego katalogu najcięższych czynów (np. zabójstwo, ciężki uszczerbek, zgwałcenie dziecka poniżej 15 lat). Przy zgłoszeniu psycholog informuje klienta i ogranicza szkody dla relacji.</p>", "src": "Bednarek, rozdz. 6", "k": ["304 kpk: bez kary", "240 kk: zamknięty katalog", "dobro klienta", "informować klienta"], "u": "etyka.html", "s": "k4"}, {"id": "edukacja/etyka-fiszki:962acbdd", "q": "Kiedy psycholog może ujawnić dokumentację lub zeznawać na wezwanie sądu?", "a": "<p>Tylko w <strong>postępowaniu karnym</strong> i po <strong>pisemnym zwolnieniu</strong> z tajemnicy (art. 180 kpk), ujawniając minimum; do dokumentacji dołącza oświadczenie o tajemnicy. W postępowaniu <strong>cywilnym</strong> zwolnienie nie jest możliwe – psycholog odmawia (art. 261 § 2 kpc). Bezprawne udostępnienie (np. kserokopie w aktach) grozi odpowiedzialnością karną i cywilną.</p>", "src": "Bednarek, rozdz. 6", "k": ["tylko karne", "pisemne zwolnienie, art. 180 kpk", "cywilne: odmowa", "minimum informacji"], "u": "etyka.html", "s": "k4"}, {"id": "edukacja/etyka-fiszki:f088f596", "q": "Na czym polega zasada minimalizacji wtargnięcia? Podaj przykłady.", "a": "<p>Psycholog przeprowadza tylko badania <strong>niezbędne</strong> do uzgodnionego celu i nie realizuje innych celów (ciekawość, badania naukowe). Przykłady naruszeń: rutynowe powtarzanie testu inteligencji bez przesłanek oraz testowanie IQ przy orzekaniu o nauczaniu w domu, gdzie wystarczą wywiad i obserwacja (warunkiem jest stan zdrowia, a klient ma prawo do niewiedzy).</p>", "src": "Bednarek, rozdz. 6", "k": ["tylko to, co niezbędne", "trzymać się celu", "powtarzanie IQ", "nauczanie domowe"], "u": "etyka.html", "s": "k5"}, {"id": "edukacja/etyka-fiszki:784522de", "q": "Jak szanować podmiotowość dziecka podczas wywiadu i omawiania wyników?", "a": "<p>Wywiad z rodzicami i omawianie wyników z rodzicami prowadzi się <strong>bez obecności dziecka</strong> – bierne słuchanie o swoich trudnościach i niezrozumiałe terminy grożą negatywnym obrazem siebie. Dziecko dostaje <strong>osobną</strong> informację zwrotną w zrozumiałym języku, z możliwością pytań. Błędy: skupienie na liczbach zamiast funkcjonowaniu, paternalizm zamiast dialogu.</p>", "src": "Bednarek, rozdz. 6", "k": ["wywiad bez dziecka", "osobna informacja dla dziecka", "język dziecka", "funkcjonowanie, nie liczby"], "u": "etyka.html", "s": "k5"}, {"id": "edukacja/etyka-fiszki:947e1827", "q": "Jak interpretować wynik testu u dziecka z innej kultury lub z rzadkim schorzeniem?", "a": "<p>Zwykle brak narzędzi z odpowiednią procedurą, więc psycholog ją modyfikuje (instrukcja w języku klienta, tłumacz objęty tajemnicą). Po modyfikacji wynik traci precyzję i staje się częściowo <strong>jakościowy</strong>, a przy nieodpowiedniej grupie normatywnej jest tylko <strong>orientacyjny</strong>. Traktowanie go jako wysoce rzetelnego to błąd.</p>", "src": "Bednarek, rozdz. 6", "k": ["modyfikacja procedury", "wynik jakościowy", "normy nieadekwatne", "tylko orientacyjnie"], "u": "etyka.html", "s": "k5"}, {"id": "edukacja/etyka-fiszki:05cc242d", "q": "Jakie prawa mają rodzice w kontakcie z psychologiem i czego nie muszą robić?", "a": "<p>Prawa m.in.: decyzja o objęciu pomocą i jej celach, pełna informacja przed zgodą, pytania, sprzeciw i odmowa odpowiedzi, zrozumiałe i pisemne wyniki, decyzja, <strong>czy i komu ujawnić opinię</strong>, decyzja o wdrażaniu zaleceń, przerwanie pomocy. Rodzice <strong>nie mają obowiązku</strong> zgody na diagnozę ani dostarczenia opinii szkole – zapis w statucie ich nie wiąże, a psycholog powinien korygować takie informacje.</p>", "src": "Bednarek, rozdz. 6", "k": ["decyzja o pomocy i celach", "decyzja o ujawnieniu opinii", "brak obowiązku diagnozy", "statut < ustawa"], "u": "etyka.html", "s": "k6"}, {"id": "edukacja/etyka-fiszki:018ea85f", "q": "Jakie warunki pracy psychologa musi zapewnić placówka?", "a": "<p>Pomieszczenie zapewniające <strong>poufność</strong> (bez osób postronnych, wyciszone), bezpieczne przechowywanie dokumentacji (bez dostępu innych pracowników), rzetelne narzędzia standardowe i <strong>oryginalne arkusze</strong> testów (kserowanie jest karalne). Ponadto wdrażanie zaleceń i szkolenie nauczycieli; dobro dziecka jest nadrzędne wobec interesu placówki (Konwencja, art. 3).</p>", "src": "Bednarek, rozdz. 6", "k": ["poufne pomieszczenie", "zabezpieczona dokumentacja", "oryginalne testy", "dobro dziecka ponad placówką"], "u": "etyka.html", "s": "k6"}, {"id": "edukacja/etyka-fiszki:3f486ec8", "q": "Kiedy psycholog może odmówić usługi?", "a": "<p>Brak kompetencji lub narzędzi (ze wskazaniem, gdzie szukać pomocy), problemy osobiste lub zdrowie, złożoność ról grożąca szkodą, zagrożenie ze strony klienta, merytoryczna niezasadność (np. powtórna diagnoza tymi samymi narzędziami), brak porozumienia co do celów (np. cel nieetyczny) oraz odmowa współpracy przez dziecko mimo prób. Nigdy z błahych powodów ani dla wygody; klienta nie zostawia się bez pomocy.</p>", "src": "Bednarek, rozdz. 6", "k": ["brak kompetencji", "złożoność ról", "zagrożenie", "cel nieetyczny", "nie dla wygody"], "u": "etyka.html", "s": "k6"}, {"id": "edukacja/etyka-fiszki:c4ae27b4", "q": "Jakie zasady podmiotowości dziecka w diagnozie wymieniają Standardy?", "a": "<p>Szacunek dla godności, prywatności i autonomii dziecka; informacja zrozumiała dla wieku i poziomu rozwoju; minimalizowanie dyskomfortu i dostosowanie procedur; prawo do poznania wyników i wyjaśnienia ich znaczenia. Dziecko jest podmiotem diagnozy, a nie tylko źródłem danych.</p>", "src": "Slajdy W6", "k": ["godność, prywatność, autonomia", "informacja dla wieku", "minimalny dyskomfort", "prawo do wyników"], "u": "etyka.html", "s": "q1"}, {"id": "edukacja/etyka-fiszki:efe72e8a", "q": "Jakie etapy obejmuje droga od diagnozy do działania?", "a": "<p>Rozpoznanie problemu → plan badania → badanie → opracowanie wyników i przekazanie informacji → planowanie i wdrażanie interwencji → ocena efektów i ewentualna modyfikacja wsparcia (model sześciu etapów ze Standardów).</p>", "src": "Slajdy W6", "k": ["rozpoznanie", "plan i badanie", "przekazanie wyników", "interwencja", "ocena efektów"], "u": "etyka.html", "s": "q1"}, {"id": "edukacja/etyka-fiszki:2c1d677b", "q": "Jakie kwalifikacje i zadania ma psycholog szkolny?", "a": "<p><strong>Kwalifikacje</strong> (§ 29 rozporządzenia z 2023 r.): wykształcenie psychologiczne i <strong>przygotowanie pedagogiczne</strong> – sam dyplom magistra nie wystarcza. <strong>Zadania</strong> (§ 24 rozporządzenia z 2017 r.): diagnoza, pomoc, profilaktyka, interwencja (mediacje, kryzysy) i współpraca z rodzicami, nauczycielami i specjalistami.</p>", "src": "Slajdy W6", "k": ["przygotowanie pedagogiczne", "diagnoza i pomoc", "profilaktyka i interwencja", "współpraca"], "u": "etyka.html", "s": "q2"}, {"id": "edukacja/etyka-fiszki:9a926ec8", "q": "Jakie są podstawowe zasady pomocy psychologiczno-pedagogicznej w szkole?", "a": "<p>Pomoc jest <strong>dobrowolna i nieodpłatna</strong>, organizuje ją <strong>dyrektor</strong>, zainicjować może ją także uczeń, wymaga współpracy z rodzicami i nauczycielami. Bieżąca pomoc w szkole to nie to samo co pogłębiona diagnoza – zgoda i procedura zależą od charakteru działania.</p>", "src": "Slajdy W6", "k": ["dobrowolna, nieodpłatna", "organizuje dyrektor", "może zainicjować uczeń", "pomoc ≠ diagnoza"], "u": "etyka.html", "s": "q2"}, {"id": "edukacja/etyka-fiszki:87b98c8c", "q": "Kiedy wchodzi w życie nowa ustawa o zawodzie psychologa i co mówi o zgodzie małoletniego?", "a": "<p>Ustawa z 23.01.2026 (Dz.U. 2026 poz. 187) obowiązuje co do zasady od <strong>19 maja 2028 r.</strong>; do tego czasu – ustawa z 2001 r. Zgodę wyraża przedstawiciel ustawowy; <strong>od 16 lat</strong> potrzebna jest też zgoda małoletniego; młodsze dziecko trzeba wysłuchać; w kryzysie lub traumie można udzielić doraźnego wsparcia bez zgody przedstawiciela.</p>", "src": "Slajdy W6", "k": ["19.05.2028", "do tego czasu ustawa z 2001", "od 16 lat zgoda małoletniego", "wyjątek: kryzys, trauma"], "u": "etyka.html", "s": "q3"}, {"id": "edukacja/etyka-fiszki:932f6f3d", "q": "Co nowa ustawa mówi o niezależności psychologa wobec dyrektora?", "a": "<p>Psycholog <strong>nie jest związany poleceniem</strong> co do treści diagnozy, opinii, orzeczenia ani doboru metod; działa zgodnie z wiedzą, etyką i należytą starannością, może konsultować wątpliwości. Dyrektor organizuje pracę placówki, ale <strong>nie określa wyniku badania</strong>.</p>", "src": "Slajdy W6", "k": ["brak związania poleceniem", "treść i metody", "dyrektor nie określa wyniku"], "u": "etyka.html", "s": "q3"}, {"id": "edukacja/etyka-fiszki:f5b7fcbf", "q": "Czy psycholog szkolny musi poinformować rodziców, gdy 15-latek prosi o pomoc i się temu sprzeciwia?", "a": "<p>Nie musi od razu przekazywać treści pierwszej rozmowy, ale <strong>nie może zagwarantować całkowitej poufności</strong>. Formalne objęcie pomocą wymaga poinformowania rodziców (§ 23), a zagrożenie bezpieczeństwa – procedur ochronnych. Trzeba odróżnić pierwszą rozmowę wspierającą, formalne objęcie pomocą i przekazywanie szczegółów.</p>", "src": "Slajdy W6", "k": ["rozmowa i ocena zagrożenia", "brak gwarancji pełnej poufności", "§ 23: informacja o objęciu pomocą", "nie wszystkie szczegóły"], "u": "etyka.html", "s": "q4"}, {"id": "edukacja/etyka-fiszki:ad062c21", "q": "Czy dyrektor może zażądać pełnej dokumentacji badania psychologicznego ucznia?", "a": "<p>Nie ma takiego ogólnego prawa. Opinia poradni trafia do szkoły co do zasady na wniosek rodzica lub pełnoletniego ucznia. Gdy badał psycholog szkolny, dyrektor ma uprawnienia organizacyjne i nadzorcze, ale nie nieograniczony dostęp do materiałów diagnostycznych i poufnych notatek. Nowa ustawa (art. 28) obejmuje dokumentację tajemnicą.</p>", "src": "Slajdy W6", "k": ["poradnia: wniosek rodzica", "szkoła: nadzór ≠ pełny dostęp", "art. 28: tajemnica"], "u": "etyka.html", "s": "q4"}, {"id": "edukacja/etyka-fiszki:4ba58db7", "q": "Jakie kompetencje przyszłości należy rozwijać według wykładu?", "a": "<p>Uczenie się (uczenie uczenia się), krytyczne i kreatywne myślenie, komunikację i współpracę, korzystanie z nowych technologii (w tym AI) oraz postępowanie etyczne i kompetencje „zielone” (ESG). Wspólna podstawa to gotowość do zmian i adaptacji.</p>", "src": "Slajdy W6", "k": ["uczenie się", "krytyczne i kreatywne myślenie", "komunikacja i współpraca", "technologie i AI", "etyka i ESG"], "u": "etyka.html", "s": "q5"}, {"id": "edukacja/etyka-fiszki:72b5335d", "q": "Jak uczyć uczenia się?", "a": "<p>Wprowadzać lekcje o uczeniu się do programu, ćwiczyć strategie poznawcze i metapoznawcze, rozwijać <strong>kontrolę aktywności strategicznej</strong> (dopasowanie strategii i technik do przedmiotu) oraz motywację do poszerzania wiedzy. Problem jest stary: szkoły nie uczą, jak się uczyć (Szycówna, Ingarden).</p>", "src": "Slajdy W6", "k": ["lekcje o uczeniu się", "strategie poznawcze i metapoznawcze", "kontrola aktywności strategicznej", "motywacja"], "u": "etyka.html", "s": "q5"}, {"id": "edukacja/cwiczenia-1-fiszki:c4cf459d", "q": "Jakie dwie funkcje wychowania wyróżnia Katra i jak je ujmuje?", "a": "<p><strong>Socjalizacyjna:</strong> dziecko ma stać się członkiem wspólnoty przez wpajanie norm społeczno-kulturowych. <strong>Emancypacyjna:</strong> przygotowanie do autonomii i samoregulacji, związanych z poczuciem podmiotowości i odpowiedzialności. Autorka traktuje je jako <strong>komplementarne</strong>.", "src": "Wychowanie, podmiotowość i rola eksperta", "k": ["socjalizacyjna: normy wspólnoty", "emancypacyjna: autonomia i samoregulacja", "komplementarne"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "edukacja/cwiczenia-1-fiszki:8d36018e", "q": "Czym jest podmiotowość według Katry (za Guryckę i Obuchowskim)?", "a": "<p>Atrybutem osoby i stanem jej umysłu: poczuciem, że potrafi projektować własną osobę i postrzegać świat na swój sposób. Oznacza <strong>motywację wewnętrzną</strong>, dojrzałość myślenia, dystans do siebie, refleksję nad zmianami i aktywny stosunek do własnej koncepcji siebie; wiąże się z samowychowaniem, autokracją i planowaniem celów osobistych.</p>", "src": "Wychowanie, podmiotowość i rola eksperta", "k": ["atrybut osoby i stan umysłu", "projektowanie własnej osoby", "motywacja wewnętrzna", "aktywny stosunek do koncepcji siebie"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "edukacja/cwiczenia-1-fiszki:3ea4a78c", "q": "Jakie kompetencje podstawowe wskazuje UE (program „Kreator”) i dlaczego to nie wystarcza?", "a": "<p>Organizowanie własnego uczenia się, skuteczne komunikowanie się, współdziałanie w zespole, twórcze rozwiązywanie problemów, posługiwanie się techniką informacyjną. Sprzyjają funkcjonowaniu we współczesnym świecie, ale <strong>nie wyczerpują</strong> warunków kształtowania podmiotowości, dlatego całość procesu wychowawczego ma ogarniać psycholog jako główny ekspert.</p>", "src": "Wychowanie, podmiotowość i rola eksperta", "k": ["uczenie się, komunikacja, praca w zespole", "rozwiązywanie problemów, technika informacyjna", "nie wyczerpują warunków podmiotowości", "psycholog jako ekspert całości"], "u": "cwiczenia-1.html", "s": "s1"}, {"id": "edukacja/cwiczenia-1-fiszki:08f083cd", "q": "Czym różni się perspektywa wewnątrz- od zewnątrzsystemowej (Jurkowski)?", "a": "<p><strong>Wewnątrzsystemowa:</strong> szkoła patrzy na siebie od środka i sprawdza, czy realizowane są jej deklarowane cele wychowawcze. <strong>Zewnątrzsystemowa:</strong> spojrzenie z zewnątrz na rzeczywiste rezultaty zjawisk w szkole, czyli faktyczne skutki dla rozwoju osobowego dziecka i jego podmiotowości.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["wewnątrzsystemowa: realizacja deklarowanych celów", "zewnątrzsystemowa: rzeczywiste skutki dla rozwoju dziecka"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:16946cc9", "q": "Jaki jest podstawowy atrybut roli psychologa szkolnego i jego główne zadanie?", "a": "<p><strong>Atrybut:</strong> autonomia wobec formalnych celów szkoły. <strong>Zadanie:</strong> śledzenie wszystkich skutków oddziaływań wychowawczych w rzeczywistości szkolnej. Psycholog jest ekspertem od wychowania i inicjatorem działań wychowawczo-korekcyjnych, który jednocześnie należy i nie należy do środowiska szkolnego.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["autonomia wobec celów szkoły", "śledzenie wszystkich skutków oddziaływań", "ekspert i inicjator działań", "należy i nie należy do szkoły"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:813b31f7", "q": "Do czego służy ekspertyza psychologa i co wychwytuje?", "a": "<p>Wychwytuje <strong>niezamierzone rezultaty</strong> ważne psychologicznie i społecznie. Jest punktem wyjścia dla działań korekcyjnych i profilaktycznych oraz podstawą postulatów wobec systemu oświaty (np. stwarzanie warunków do rozwoju samoregulacji), co czyni psychologa inicjatorem pożądanych oddziaływań.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["niezamierzone rezultaty", "podstawa działań korekcyjnych i profilaktycznych", "postulaty wobec systemu oświaty"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:7c9d44d1", "q": "Jakie rozbieżności wskazuje psycholog, optymalizując proces wychowania szkolnego?", "a": "<p>Między <strong>deklarowanymi a rzeczywistymi wymaganiami</strong> nauczycieli oraz między <strong>zamierzonymi a rzeczywistymi efektami</strong> pracy dydaktyczno-wychowawczej. Formułuje zalecenia je likwidujące lub zmniejszające i kreuje optymalne sytuacje wychowawcze.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["deklarowane a rzeczywiste wymagania nauczycieli", "zamierzone a rzeczywiste efekty", "zalecenia zmniejszające rozbieżności"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:8a4a86ae", "q": "Dlaczego rola eksperta jest w praktyce niedoceniana i jak psycholog może zyskać autonomię?", "a": "<p>Wymaga wyjścia poza system szkoły i oświaty, a psycholog jest podporządkowany dyrektorowi, więc trudno mu wyjść z roli usługodawcy. Może dążyć do indywidualnej autonomii: oferować potrzebne jego zdaniem działania <strong>bez oczekiwania na zapotrzebowanie zewnętrzne</strong>.</p>", "src": "Perspektywa zewnątrzsystemowa i zadania psychologa", "k": ["wymaga wyjścia poza system szkoły", "podporządkowanie dyrektorowi", "oferowanie działań bez zapotrzebowania"], "u": "cwiczenia-1.html", "s": "s2"}, {"id": "edukacja/cwiczenia-1-fiszki:7867e3a3", "q": "Jakie cztery rodzaje działań wyróżnia Katra i jak są powiązane?", "a": "<p>Monitoring, psychoprofilaktyka, interwencja i promocja. <strong>Monitoring jest bazą</strong> dla pozostałych. Profilaktyka, interwencja i promocja mogą być prowadzone równocześnie albo chronologicznie (np. przy agresji: interwencja, profilaktyka trzeciorzędowa, promocja).</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["monitoring", "psychoprofilaktyka", "interwencja", "promocja", "monitoring bazą dla pozostałych"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:45a13768", "q": "Jakie standardy weryfikacji przyjmuje psycholog w monitoringu i do jakich koncepcji się odwołuje?", "a": "<p><strong>Spójność</strong> założonych celów i rzeczywistych konsekwencji oddziaływań oraz <strong>odpowiedniość</strong> tych konsekwencji wobec nadrzędnego celu (rozwój i samoregulacja dla satysfakcjonującej jakości życia, z prawem do godności i szacunku). Koncepcje: doświadczenia Guryckiej (1979) i interakcji wychowawczych Dryll (2001).</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["spójność celów i konsekwencji", "odpowiedniość wobec nadrzędnego celu (rozwój)", "Gurycka: doświadczenia", "Dryll: interakcje wychowawcze"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:41bfdd43", "q": "Czym różnią się trzy poziomy psychoprofilaktyki i który nie jest zadaniem psychologa szkolnego?", "a": "<p><strong>Pierwszorzędowa:</strong> szeroki krąg, niskie ryzyko, promocja zdrowego stylu życia. <strong>Drugorzędowa:</strong> zachowania ryzykowne już się pojawiły, ale nie chronicznie (agresywni, nieśmiali, odrzuceni). <strong>Trzeciorzędowa:</strong> permanentne zachowania ryzykowne, powrót po leczeniu; <strong>nie należy</strong> do zadań psychologa szkolnego.</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["pierwszorzędowa: szeroki krąg, niskie ryzyko", "drugorzędowa: zachowania ryzykowne się pojawiły", "trzeciorzędowa: utrwalone, po leczeniu", "trzeciorzędowa nie jest zadaniem psychologa szkolnego"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:15dabe9d", "q": "Na czym polega interwencja i promocja w pracy psychologa szkolnego?", "a": "<p><strong>Interwencja:</strong> przy wyraźnych problemach; porady, zalecenia, modyfikacja postaw rodziców i nauczycieli, naprawa błędów wychowawczych, rozwiązywanie konfliktów i mediacje. <strong>Promocja:</strong> tworzenie warunków do wykorzystania potencjału ucznia; kompetencje komunikacyjne, przewidywanie konsekwencji, samoregulacja, podnoszenie samooceny.</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["interwencja przy wyraźnych problemach", "porady, mediacje, rozwiązywanie konfliktów", "promocja: wykorzystanie potencjału ucznia", "samoregulacja, samoocena"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:3aac06a2", "q": "Jakie zasady etyczne obowiązują psychologa (także szkolnego)?", "a": "<p>Tajemnica zawodowa, bezstronność, przejrzystość i rzetelna informacja o zamierzeniach, efektach i celu interakcji, zawieranie jasnej umowy dotyczącej tej interakcji.</p>", "src": "Cztery rodzaje działań psychologa szkolnego", "k": ["tajemnica zawodowa", "bezstronność", "przejrzystość i rzetelna informacja", "jasna umowa"], "u": "cwiczenia-1.html", "s": "s3"}, {"id": "edukacja/cwiczenia-1-fiszki:e43804e7", "q": "Jakie formy i kompetencje obejmuje monitoring w Tabeli 2?", "a": "<p><strong>Formy:</strong> obserwacja i analiza, ekspertyza, monografia klasy, rozmowa lub wywiad, spotkania z klasą, rodzicami i nauczycielami. <strong>Kompetencje:</strong> obserwacja uczestnicząca, monografia klasy, metody socjometryczne, nawiązywanie kontaktu i współpracy ze środowiskiem szkolnym, prowadzenie wywiadu.</p>", "src": "Tabela 2: charakterystyka działań", "k": ["obserwacja i analiza", "ekspertyza, monografia klasy", "wywiad, spotkania", "metody socjometryczne"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "edukacja/cwiczenia-1-fiszki:19acf0bb", "q": "Jakie są formy, funkcje i mechanizmy psychoprofilaktyki w Tabeli 2?", "a": "<p><strong>Formy:</strong> szerzenie wiedzy, perswazja, praca z grupą (warsztaty, treningi). <strong>Funkcje:</strong> podnoszenie kompetencji wychowawczych wychowawców i interpersonalnych wychowanków, odporność na niekorzystne wpływy, samoregulacja. <strong>Mechanizmy:</strong> kształtowanie środowiska przez zmiany w elementach systemu, niwelowanie rozbieżności między wzorcem a stanem faktycznym, samokontrola.</p>", "src": "Tabela 2: charakterystyka działań", "k": ["szerzenie wiedzy, perswazja, praca z grupą", "kompetencje wychowawców i wychowanków", "odporność, samoregulacja", "niwelowanie rozbieżności, samokontrola"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "edukacja/cwiczenia-1-fiszki:c63c5f1f", "q": "Czym według Tabeli 2 charakteryzuje się interwencja, a czym promocja?", "a": "<p><strong>Interwencja:</strong> cel to przywracanie korzystnych warunków wychowawczych; formy to porada, indywidualna pomoc, praca systemowa; mechanizmy to zasoby i strategie radzenia sobie ze stresem, kompensacja, nowe schematy; kompetencje obejmują mediację i arbitraż. <strong>Promocja:</strong> cel to formowanie osobowości zgodnie z potencjałem; formy to kształtowanie środowiska, treningi, warsztaty, wzorce; mechanizmy to nowe schematy i <strong>modelowanie</strong>.</p>", "src": "Tabela 2: charakterystyka działań", "k": ["interwencja: przywracanie korzystnych warunków", "porada, pomoc indywidualna, praca systemowa", "mediacja i arbitraż", "promocja: rozwój zgodnie z potencjałem", "modelowanie"], "u": "cwiczenia-1.html", "s": "s4"}, {"id": "edukacja/cwiczenia-1-fiszki:fea4d487", "q": "Czym są umiejętności społeczno-emocjonalne według Eliasa i dlaczego warto je rozwijać razem z poznawczymi?", "a": "<p>Zwane też inteligencją emocjonalną; pozwalają współpracować, skutecznie się uczyć i pełnić role w rodzinie, społeczeństwie i pracy. <strong>Można ich nauczyć</strong> i wpływają pozytywnie na uczenie się. Gdy rozwój poznawczy i społeczno-emocjonalny idą razem, uczniowie lepiej zapamiętują materiał, czują odpowiedzialność i są bardziej zmotywowani.</p>", "src": "Uczenie się poznawcze i społeczno-emocjonalne", "k": ["inteligencja emocjonalna", "współpraca, uczenie się, role społeczne", "można się ich nauczyć", "lepsze zapamiętywanie i motywacja"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "edukacja/cwiczenia-1-fiszki:bf5d2a2d", "q": "Dlaczego inteligencja społeczno-emocjonalna jest „brakującym ogniwem”?", "a": "<p>Łączy zdobywanie wiedzy z umiejętnościami potrzebnymi do sukcesu w szkole, domu, społeczeństwie, pracy i życiu. W szkołach z dobrze realizowanymi programami uczniowie osiągają lepsze wyniki, jest mniej problemów z zachowaniem i lepsze relacje ze środowiskiem.</p>", "src": "Uczenie się poznawcze i społeczno-emocjonalne", "k": ["łączy wiedzę z umiejętnościami do sukcesu", "lepsze wyniki", "mniej problemów z zachowaniem"], "u": "cwiczenia-1.html", "s": "s5"}, {"id": "edukacja/cwiczenia-1-fiszki:82ea7084", "q": "Czym jest CASEL i jakie cztery grupy umiejętności wyodrębnił?", "a": "<p>Organizacja non-profit badająca edukację w nurcie SEL, założona w 1994 r. przez Golemana i Growald. Cztery grupy (16 umiejętności): <strong>poznaj siebie i innych</strong>, <strong>podejmuj odpowiedzialne decyzje</strong>, <strong>dbaj o innych</strong>, <strong>wiedz, jak trzeba postępować</strong>.</p>", "src": "Umiejętności społeczno-emocjonalne według CASEL", "k": ["organizacja non-profit SEL (1994, Goleman)", "poznaj siebie i innych", "podejmuj odpowiedzialne decyzje", "dbaj o innych", "wiedz, jak postępować"], "u": "cwiczenia-1.html", "s": "s6"}, {"id": "edukacja/cwiczenia-1-fiszki:ef5700b7", "q": "Co mówią zasady 1–2 Eliasa (życzliwość, umiejętności życiowe)?", "a": "<p><strong>1:</strong> podstawą rozwoju są serdeczne relacje w życzliwym, ale wymagającym otoczeniu (bez strachu, z wyzwaniami; jasne, sprawiedliwe, konsekwentne reguły). <strong>2:</strong> na każdym etapie uczyć praktycznych umiejętności życiowych (lista CASEL), np. włączać jedną umiejętność tygodniowo do rutyny.</p>", "src": "Dziesięć zasad Eliasa: zasady 1–5", "k": ["serdeczne relacje w wymagającym otoczeniu", "jasne, sprawiedliwe reguły", "uczenie umiejętności życiowych"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "edukacja/cwiczenia-1-fiszki:bb4a5322", "q": "Co mówią zasady 3–4 Eliasa (spójna polityka szkoły, cele)?", "a": "<p><strong>3:</strong> spójna polityka szkoły (programy prewencji, zdrowy styl życia, wsparcie dzieci w trudnych sytuacjach); pomoc zwykle pojawia się za późno. <strong>4:</strong> wyznaczanie celów i rozwiązywanie problemów nadaje kierunek uczeniu się; uczniowie bardziej zaangażowani, gdy rozumieją cele i znają strategie rozwiązywania problemów (schemat analizy wydarzeń historycznych).</p>", "src": "Dziesięć zasad Eliasa: zasady 1–5", "k": ["spójna polityka szkoły", "prewencja i wsparcie", "wyznaczanie celów", "rozwiązywanie problemów"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "edukacja/cwiczenia-1-fiszki:60a13d4e", "q": "Co mówi zasada 5 Eliasa o procedurach nauczania?", "a": "<p>Należy stosować <strong>zróżnicowane procedury</strong> odwołujące się do różnych zmysłów i zainteresowań (role, sztuka, taniec, teatr, media cyfrowe), zmieniać formy pracy, dawać regularną konstruktywną informację zwrotną i zadawać pytania otwarte, bo rozwój poznawczy i społeczno-emocjonalny przebiega u uczniów różnie.</p>", "src": "Dziesięć zasad Eliasa: zasady 1–5", "k": ["zróżnicowane procedury", "różne zmysły i zainteresowania", "konstruktywna informacja zwrotna", "pytania otwarte"], "u": "cwiczenia-1.html", "s": "s7"}, {"id": "edukacja/cwiczenia-1-fiszki:1407f899", "q": "Co mówią zasady 6–7 Eliasa (społeczność lokalna, rodzice)?", "a": "<p><strong>6:</strong> praca na rzecz społeczności rozwija empatię; fazy: przygotowanie, działanie, refleksja, prezentacja. <strong>7:</strong> współpraca szkoły i domu daje trwalsze efekty; regularnie informować rodziców, umożliwiać spotkania i udział w życiu szkoły.</p>", "src": "Dziesięć zasad Eliasa: zasady 6–10", "k": ["praca dla społeczności rozwija empatię", "przygotowanie, działanie, refleksja, prezentacja", "współpraca szkoły i domu"], "u": "cwiczenia-1.html", "s": "s8"}, {"id": "edukacja/cwiczenia-1-fiszki:9102f74f", "q": "Co mówią zasady 8–9 Eliasa (wdrażanie, nauczyciele)?", "a": "<p><strong>8:</strong> programy wprowadza się stopniowo, jako projekty pilotażowe, a kompetentnie czuje się wdrażający dopiero po 2–3 latach; SEL nie jest osobnym przedmiotem. <strong>9:</strong> skuteczność zależy od ciągłego doskonalenia zawodowego i wsparcia całego personelu, zwłaszcza w pierwszych latach wdrażania.</p>", "src": "Dziesięć zasad Eliasa: zasady 6–10", "k": ["wdrażanie stopniowe, pilotaż", "kompetencja po 2–3 latach", "SEL nie osobnym przedmiotem", "ciągłe doskonalenie personelu"], "u": "cwiczenia-1.html", "s": "s8"}, {"id": "edukacja/cwiczenia-1-fiszki:23c0d649", "q": "Dlaczego zasada 10 Eliasa traktuje ewaluację jako zadanie etyczne?", "a": "<p>Szkoła, przyjmując ucznia, zobowiązuje się przygotować go do przyszłości, ale nie gwarantuje rezultatów, więc ma <strong>etyczny obowiązek monitorowania</strong> i ciągłego udoskonalania pracy. Informacje zbiera z wielu źródeł: opinie szkolonych i szkolących, dokumentacja wdrażania, wyniki różnych grup uczniów, bieżące wydarzenia.</p>", "src": "Dziesięć zasad Eliasa: zasady 6–10", "k": ["szkoła zobowiązuje się przygotować ucznia", "brak gwarancji rezultatów", "obowiązek monitorowania i ulepszania", "dane z wielu źródeł"], "u": "cwiczenia-1.html", "s": "s8"}, {"id": "edukacja/cwiczenia-1-fiszki:e2e6847c", "q": "Jakie główne wnioski formułuje Elias na zakończenie?", "a": "<p>Kształcenie poznawcze i społeczno-emocjonalne staje się nowym standardem podstaw szkolnych. Celem jest szkoła, w której nauka jest doceniana, a talenty rozwijają się swobodnie; każdy uczeń ma inny potencjał. Zadanie wymaga cierpliwości i wielkiego wysiłku.</p>", "src": "Zakończenie", "k": ["nowy standard kształcenia", "nauka doceniana, talenty rozwijane", "różny potencjał uczniów", "cierpliwość i wysiłek"], "u": "cwiczenia-1.html", "s": "s9"}];
